pub fn write_results(out_dir: &str, results: &JsonValue) -> Result<()> {
    fs::create_dir_all(out_dir)?;
    if !results["artifact_configuration"].is_null() {
        let path = Path::new(out_dir).join("artifact_configuration.json");
        fs::write(
            path,
            serde_json::to_vec_pretty(&results["artifact_configuration"])?,
        )?;
    }
    for key in [
        "correctness",
        "static_checks",
        "bridge_validation",
        "trace_equivalence",
        "leakage_auc",
        "mutual_information",
        "overheads",
        "controller_observer_validation",
        "pathoram_hidden_validation",
        "runtime_boundary_validation",
        "runtime_implementation_interface_validation",
        "runtime_small_confidential_kernel_boundary_validation",
        "runtime_public_bridge_boundary_validation",
        "runtime_slot_adapter_boundary_validation",
        "runtime_residual_helper_shell_boundary_validation",
        "runtime_implementation_public_bridge_observer_refinement_boundary_validation",
        "runtime_implementation_residual_helper_shell_machine_refinement_boundary_validation",
        "runtime_confidential_statement_trace_bridge_boundary_validation",
        "runtime_implementation_slot_adapter_machine_refinement_boundary_validation",
        "runtime_implementation_small_confidential_kernel_machine_refinement_boundary_validation",
        "runtime_implementation_confidential_statement_trace_bridge_refinement_boundary_validation",
        "runtime_implementation_kernel_meeting_boundary_validation",
        "runtime_implementation_kernel_meeting_confinement_boundary_validation",
        "runtime_implementation_kernel_machine_confinement_boundary_validation",
        "runtime_shared_confidential_kernel_boundary_validation",
        "runtime_kernel_machine_finish_witness_validation",
        "runtime_kernel_machine_finish_boundary_validation",
        "runtime_implementation_shared_kernel_machine_refinement_boundary_validation",
        "runtime_implementation_shared_kernel_refinement_boundary_validation",
        "runtime_implementation_confinement_boundary_validation",
        "kernel_model_alignment_validation",
        "shell_boundary_validation",
        "shell_boundary_slot_validation",
        "shell_boundary_lowering_validation",
        "confidential_fragment_validation",
        "kernel_dsl_validation",
        "kernel_slot_dsl_validation",
        "kernel_lowering_validation",
        "confidential_core_validation",
        "confidential_core_slot_validation",
        "confidential_core_kernel_finish_slot_validation",
        "confidential_core_shell_boundary_slot_validation",
        "confidential_core_kernel_interface_slot_validation",
        "confidential_core_kernel_interface_slot_finish_boundary_validation",
        "kernel_slot_boundary_validation",
        "confidential_proof_family_validation",
        "confidential_proof_family_assurance_validation",
        "confidential_proof_family_boundary_validation",
        "confidential_proof_family_kernel_interface_validation",
        "confidential_proof_family_slot_assurance_validation",
        "confidential_proof_family_slot_boundary_validation",
        "confidential_proof_family_finish_slot_boundary_validation",
        "confidential_proof_family_refinement_boundary_validation",
        "confidential_core_lowering_validation",
        "confidential_core_shell_boundary_lowering_validation",
        "kernel_validation",
        "kernel_refinement_validation",
        "trusted_kernel_validation",
        "tamper_validation",
        "witness_validation",
        "kernel_interface_validation",
        "kernel_interface_singleton_boundary_validation",
        "kernel_interface_confinement_boundary_validation",
        "kernel_finish_boundary_validation",
        "kernel_refinement_boundary_validation",
        "kernel_confinement_boundary_validation",
        "seeded_witness_validation",
        "paper_main_family_boundary_validation",
        "paper_main_slot_boundary_validation",
        "fresh_coin_validation",
        "pathoram_pair_validation",
        "canonical_pathoram_pair_validation",
        "reviewer_summary",
    ] {
        let path = Path::new(out_dir).join(format!("{key}.json"));
        fs::write(path, serde_json::to_vec_pretty(&results[key])?)?;
    }
    fs::write(
        Path::new(out_dir).join("artifact_readme.md"),
        results["artifact_readme"]
            .as_str()
            .ok_or_else(|| anyhow!("artifact_readme missing"))?,
    )?;
    if !results["reviewer_summary"].is_null() {
        write_reviewer_summary_markdown(out_dir, &results["reviewer_summary"])?;
    }
    write_reproducibility_manifest(out_dir)?;
    Ok(())
}

pub fn write_reproducibility_manifest(out_dir: &str) -> Result<()> {
    let root = Path::new(out_dir);
    fs::create_dir_all(root)?;
    let lean_toolchain = read_lean_toolchain_pin()?;
    let lean_toolchain_exact_release = lean_toolchain_exact_release_pinned(&lean_toolchain);
    if !lean_toolchain_exact_release {
        bail!(
            "Lean toolchain must be pinned to an exact release, found `{}`; expected `{}`",
            lean_toolchain,
            EXPECTED_LEAN_TOOLCHAIN_PIN
        );
    }
    let (lean_version, lake_version) = lean_lake_version_strings()?;
    let rust_toolchain_channel = read_rust_toolchain_channel()?;
    let rust_toolchain_exact_release = rust_toolchain_exact_release_pinned(&rust_toolchain_channel);
    if !rust_toolchain_exact_release {
        bail!(
            "Rust toolchain must be pinned to an exact release, found `{}`; expected `{}`",
            rust_toolchain_channel,
            EXPECTED_RUST_TOOLCHAIN_CHANNEL
        );
    }
    let (rustc_version, cargo_version) = rust_cargo_version_strings()?;
    let rust_toolchain_sha256 = file_sha256_hex(&repo_root().join("rust-toolchain.toml"))?;
    let cargo_lock_sha256 = file_sha256_hex(&repo_root().join("Cargo.lock"))?;
    let mut files = Vec::new();
    collect_bundle_files(root, root, &mut files)?;
    let entries = files
        .into_iter()
        .filter(|path| {
            path.file_name().and_then(|name| name.to_str()) != Some("reproducibility_manifest.json")
        })
        .map(|path| {
            let bytes = fs::read(&path)
                .with_context(|| format!("reading output file {}", path.display()))?;
            let relative = path
                .strip_prefix(root)
                .unwrap_or(&path)
                .display()
                .to_string();
            Ok(ReproducibilityManifestEntry {
                path: relative,
                bytes: bytes.len() as u64,
                sha256: hex::encode(Sha256::digest(&bytes)),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let manifest = ReproducibilityManifest {
        format_version: 3,
        file_count: entries.len(),
        lean_toolchain,
        lean_toolchain_exact_release,
        lean_version,
        lake_version,
        rust_toolchain_channel,
        rust_toolchain_exact_release,
        rust_toolchain_sha256,
        rustc_version,
        cargo_version,
        cargo_lock_sha256,
        files: entries,
    };
    fs::write(
        root.join("reproducibility_manifest.json"),
        serde_json::to_vec_pretty(&manifest)?,
    )?;
    Ok(())
}

fn proof_lean_dir() -> PathBuf {
    repo_root().join("proof/lean")
}

fn read_lean_toolchain_pin() -> Result<String> {
    let path = proof_lean_dir().join("lean-toolchain");
    fs::read_to_string(&path)
        .with_context(|| format!("reading {}", display_report_path(&path)))
        .map(|source| source.trim().to_owned())
}

fn lean_toolchain_exact_release_pinned(toolchain: &str) -> bool {
    toolchain == EXPECTED_LEAN_TOOLCHAIN_PIN
        && toolchain.starts_with("leanprover/lean4:v")
        && !toolchain.contains(":stable")
}

fn read_rust_toolchain_channel() -> Result<String> {
    let path = repo_root().join("rust-toolchain.toml");
    let source =
        fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
    source
        .lines()
        .find_map(|line| {
            let trimmed = line.trim();
            trimmed
                .strip_prefix("channel")
                .and_then(|rest| rest.trim_start().strip_prefix('='))
                .map(|value| value.trim().trim_matches('"').to_owned())
        })
        .filter(|channel| !channel.is_empty())
        .ok_or_else(|| anyhow!("missing channel in {}", path.display()))
}

fn rust_toolchain_exact_release_pinned(channel: &str) -> bool {
    channel == EXPECTED_RUST_TOOLCHAIN_CHANNEL
        && !channel.contains("stable")
        && !channel.contains("nightly")
        && !channel.contains("beta")
}

fn command_stdout_trimmed(command: &str, args: &[&str], cwd: &Path) -> Result<String> {
    let output = Command::new(command)
        .args(args)
        .current_dir(cwd)
        .output()
        .with_context(|| format!("running `{}` in {}", command, cwd.display()))?;
    if !output.status.success() {
        return Err(anyhow!(
            "`{}` failed with status {}\nstdout:\n{}\nstderr:\n{}",
            command,
            output.status,
            String::from_utf8_lossy(&output.stdout).trim(),
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_owned())
}

fn lean_lake_version_strings() -> Result<(String, String)> {
    let lean_dir = proof_lean_dir();
    let lean_version = command_stdout_trimmed("lean", &["--version"], &lean_dir)?;
    let lake_version = command_stdout_trimmed("lake", &["--version"], &lean_dir)?;
    Ok((lean_version, lake_version))
}

fn rust_cargo_version_strings() -> Result<(String, String)> {
    let root = repo_root();
    let rustc_version = command_stdout_trimmed("rustc", &["--version"], &root)?;
    let cargo_version = command_stdout_trimmed("cargo", &["--version"], &root)?;
    Ok((rustc_version, cargo_version))
}

fn file_sha256_hex(path: &Path) -> Result<String> {
    let bytes = fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    Ok(hex::encode(Sha256::digest(&bytes)))
}

fn collect_bundle_files(root: &Path, dir: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
    let mut entries = fs::read_dir(dir)
        .with_context(|| format!("reading output directory {}", dir.display()))?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    entries.sort_by(|lhs, rhs| lhs.path().cmp(&rhs.path()));
    for entry in entries {
        let path = entry.path();
        let file_type = entry
            .file_type()
            .with_context(|| format!("reading file type for {}", path.display()))?;
        if file_type.is_dir() {
            collect_bundle_files(root, &path, files)?;
        } else if file_type.is_file() {
            files.push(path);
        }
    }
    files.sort_by(|lhs, rhs| {
        lhs.strip_prefix(root)
            .unwrap_or(lhs)
            .cmp(rhs.strip_prefix(root).unwrap_or(rhs))
    });
    Ok(())
}

pub fn write_reviewer_summary_markdown(out_dir: &str, summary: &JsonValue) -> Result<()> {
    fs::write(
        Path::new(out_dir).join("reviewer_summary.md"),
        render_reviewer_summary_markdown(summary)?,
    )?;
    Ok(())
}

fn render_reviewer_summary_markdown(summary: &JsonValue) -> Result<String> {
    let mut out = String::from("# Reviewer Summary\n\n");

    out.push_str("## Proof And Report Cost\n\n");
    out.push_str("| Report | Milliseconds |\n");
    out.push_str("| --- | ---: |\n");
    if let Some(costs) = summary["proof_checking_cost_ms"].as_object() {
        let mut rows = costs
            .iter()
            .filter_map(|(name, value)| value.as_u64().map(|ms| (name.as_str(), ms)))
            .collect::<Vec<_>>();
        rows.sort_by(|lhs, rhs| rhs.1.cmp(&lhs.1).then_with(|| lhs.0.cmp(rhs.0)));
        for (name, ms) in rows {
            out.push_str(&format!("| `{}` | `{}` |\n", name, ms));
        }
    }
    out.push('\n');

    out.push_str("## Largest Materialized Artifacts\n\n");
    out.push_str("| Report Field | Bytes |\n");
    out.push_str("| --- | ---: |\n");
    if let Some(entries) =
        summary["artifact_size_bytes"]["top_materialized_report_fields"].as_array()
    {
        for entry in entries {
            let metric = entry["metric"].as_str().unwrap_or("unknown");
            let bytes = entry["bytes"].as_u64().unwrap_or_default();
            out.push_str(&format!("| `{}` | `{}` |\n", metric, bytes));
        }
    }
    out.push('\n');

    out.push_str("## Largest Estimated Artifacts\n\n");
    out.push_str("| Report Field | Estimated Bytes |\n");
    out.push_str("| --- | ---: |\n");
    if let Some(entries) = summary["artifact_size_bytes"]["top_estimated_report_fields"].as_array()
    {
        for entry in entries {
            let metric = entry["metric"].as_str().unwrap_or("unknown");
            let bytes = entry["bytes"].as_u64().unwrap_or_default();
            out.push_str(&format!("| `{}` | `{}` |\n", metric, bytes));
        }
    }
    out.push('\n');

    out.push_str("## Proof Artifact Size Budgets\n\n");
    out.push_str("| Check | Value |\n");
    out.push_str("| --- | ---: |\n");
    let budget = &summary["proof_artifact_size_budget"];
    out.push_str(&format!(
        "| Compact budget bytes | `{}` |\n",
        budget["compact_budget_bytes"].as_u64().unwrap_or_default()
    ));
    out.push_str(&format!(
        "| Heavy-artifact budget bytes | `{}` |\n",
        budget["heavy_budget_bytes"].as_u64().unwrap_or_default()
    ));
    out.push_str(&format!(
        "| Oversized estimates | `{}` |\n",
        budget["oversized_estimate_count"]
            .as_u64()
            .unwrap_or_default()
    ));
    out.push_str(&format!(
        "| Theorem-facing large artifacts require enumeration | `{}` |\n",
        budget["theorem_facing_large_artifacts_require_enumeration"]
            .as_bool()
            .unwrap_or(true)
    ));
    out.push_str(&format!(
        "| Accepted | `{}` |\n",
        budget["accepted"].as_bool().unwrap_or(false)
    ));
    out.push('\n');
    out.push_str("| Scenario | Status | Estimated Bytes | Checked Bytes | Within Budget |\n");
    out.push_str("| --- | --- | ---: | ---: | --- |\n");
    if let Some(rows) = budget["scenarios"].as_array() {
        for row in rows {
            out.push_str(&format!(
                "| `{}` | `{}` | `{}` | `{}` | `{}` |\n",
                row["scenario"].as_str().unwrap_or("unknown"),
                row["validation_status"].as_str().unwrap_or("unknown"),
                row["estimated_json_bytes"].as_u64().unwrap_or_default(),
                row["checked_json_bytes"].as_u64().unwrap_or_default(),
                row["checked_artifact_within_selected_budget"]
                    .as_bool()
                    .unwrap_or(false),
            ));
        }
    }
    out.push('\n');

    out.push_str("## Runtime Overheads\n\n");
    out.push_str(
        "| Benchmark | Backend | Capacity | Gas | Reads | Writes | Bytes Read | Bytes Written | Trace JSON Bytes | Artifact JSON Bytes | Max Commit Ops |\n",
    );
    out.push_str("| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |\n");
    if let Some(rows) = summary["runtime_overheads"]["matrix"].as_array() {
        for row in rows {
            let overhead_cell = |field: &str| -> String {
                if row["rejected"].as_bool() == Some(true) {
                    return "rejected".to_string();
                }
                if let Some(number) = row[field].as_u64() {
                    return number.to_string();
                }
                if let Some(number) = row[field].as_f64() {
                    return number.to_string();
                }
                "n/a".to_string()
            };
            out.push_str(&format!(
                "| `{}` | `{}` | `{}` | `{}` | `{}` | `{}` | `{}` | `{}` | `{}` | `{}` | `{}` |\n",
                row["benchmark"].as_str().unwrap_or("unknown"),
                row["backend"].as_str().unwrap_or("unknown"),
                row["capacity"]
                    .as_str()
                    .or_else(|| row["capacity"].as_u64().map(|_| ""))
                    .unwrap_or("n/a"),
                overhead_cell("gas_used"),
                overhead_cell("physical_reads"),
                overhead_cell("physical_writes"),
                overhead_cell("bytes_read"),
                overhead_cell("bytes_written"),
                overhead_cell("trace_json_bytes"),
                row["artifact_json_bytes"].as_u64().unwrap_or_default(),
                row["entrypoint_resource_bounds"]["max_commit_ops"]
                    .as_u64()
                    .unwrap_or_default(),
            ));
        }
    } else if let Some(cases) = summary["runtime_overheads"]["cases"].as_array() {
        for case in cases {
            let overhead_cell = |section: &str, field: &str| -> String {
                let value = &case[section];
                if value["rejected"].as_bool() == Some(true) {
                    return "rejected".to_string();
                }
                if let Some(number) = value[field].as_u64() {
                    return number.to_string();
                }
                if let Some(number) = value[field].as_f64() {
                    return number.to_string();
                }
                "n/a".to_string()
            };
            out.push_str(&format!(
                "| `{}` | `raw` | `n/a` | `{}` | `n/a` | `{}` | `n/a` | `{}` | `n/a` | `n/a` | `n/a` |\n",
                case["benchmark"].as_str().unwrap_or("unknown"),
                overhead_cell("raw", "gas_used"),
                overhead_cell("raw", "physical_writes"),
                overhead_cell("raw", "bytes_written"),
            ));
        }
    }
    out.push('\n');

    out.push_str("## TCB Surface\n\n");
    out.push_str("| Surface | Total Non-Empty LOC |\n");
    out.push_str("| --- | ---: |\n");
    out.push_str(&format!(
        "| Trusted Rust runtime surface | `{}` |\n",
        summary["tcb_size"]["trusted_runtime_surface"]["total_nonempty_loc"]
            .as_u64()
            .unwrap_or_default()
    ));
    out.push_str(&format!(
        "| Outer runtime risk surface | `{}` |\n",
        summary["tcb_size"]["outer_runtime_risk_surface"]["total_nonempty_loc"]
            .as_u64()
            .unwrap_or_default()
    ));
    out.push_str(&format!(
        "| Lean theorem/checker repo surface | `{}` |\n",
        summary["tcb_size"]["lean_theorem_checker_repo_surface"]["total_nonempty_loc"]
            .as_u64()
            .unwrap_or_default()
    ));
    out.push('\n');

    out.push_str("## Current TCB Table\n\n");
    out.push_str("| Component | In Current Proof-Grade TCB? | Role |\n");
    out.push_str("| --- | --- | --- |\n");
    if let Some(entries) = summary["current_tcb"].as_array() {
        for entry in entries {
            out.push_str(&format!(
                "| {} | `{}` | {} |\n",
                markdown_escape(entry["component"].as_str().unwrap_or("unknown")),
                entry["in_current_proofgrade_tcb"]
                    .as_bool()
                    .unwrap_or(false),
                markdown_escape(entry["role"].as_str().unwrap_or("unknown")),
            ));
        }
    }
    out.push('\n');

    out.push_str("## Explicit Assumptions\n\n");
    out.push_str("| Assumption | Meaning | Status |\n");
    out.push_str("| --- | --- | --- |\n");
    if let Some(entries) = summary["explicit_assumptions"].as_array() {
        for entry in entries {
            out.push_str(&format!(
                "| `{}` | {} | {} |\n",
                entry["assumption"].as_str().unwrap_or("unknown"),
                markdown_escape(entry["meaning"].as_str().unwrap_or("unknown")),
                markdown_escape(entry["status"].as_str().unwrap_or("unknown")),
            ));
        }
    }
    out.push('\n');

    out.push_str("## TEE Observer Closure Audit\n\n");
    out.push_str(
        "Mirrors the `sgxHostileHostClosureAudit` Lean record in \
        `proof/lean/UOToolchain/SgxObserverFreeze.lean`. The Lean \
        closure-audit theorems pin the same content at the type \
        level: `sgxHostileHostClosureAudit_length` (= 6), \
        `sgxHostileHostClosureAudit_leanProvedEntries` (W6.1–W6.4 \
        Lean-proved), `sgxHostileHostClosureAudit_allClassified`, \
        and `sgxHostileHostClosureAudit_driftCheckNames`.\n\n",
    );
    out.push_str("| Checkpoint | Role | Classification | Lean Anchor | Static-Drift Check |\n");
    out.push_str("| --- | --- | --- | --- | --- |\n");
    if let Some(entries) = summary["wp6_closure_audit"].as_array() {
        for entry in entries {
            out.push_str(&format!(
                "| `{}` | {} | {} | `{}` | `{}` |\n",
                entry["checkpoint"].as_str().unwrap_or("unknown"),
                markdown_escape(entry["role"].as_str().unwrap_or("unknown")),
                entry["classification"].as_str().unwrap_or("unknown"),
                entry["lean_anchor"].as_str().unwrap_or("unknown"),
                entry["static_drift_check_name"]
                    .as_str()
                    .unwrap_or("unknown"),
            ));
        }
    }
    out.push('\n');

    out.push_str("## Static-Drift Check Inventory\n\n");
    out.push_str(
        "Every named static-drift check the probe runs at every gated \
        validation slice. The acceptance gate requires every listed \
        check to be `true` in the corresponding report field.\n\n",
    );
    out.push_str("| Static-Drift Check | Surface | Target | Report Field |\n");
    out.push_str("| --- | --- | --- | --- |\n");
    if let Some(entries) = summary["static_drift_check_inventory"].as_array() {
        for entry in entries {
            out.push_str(&format!(
                "| `{}` | `{}` | {} | `{}` |\n",
                entry["name"].as_str().unwrap_or("unknown"),
                entry["work_package"].as_str().unwrap_or("unknown"),
                markdown_escape(entry["target"].as_str().unwrap_or("unknown")),
                entry["report_field"].as_str().unwrap_or("unknown"),
            ));
        }
    }

    out.push('\n');
    out.push_str("## Benchmark Overhead\n\n");
    out.push_str(
        "Executable overhead rows for every benchmark backend. `gas_used` is a \
        modeled resource cost, not stock EVM gas (see `cost_model` in \
        `overheads.json`).\n\n",
    );
    out.push_str("| Benchmark | Backend | Modeled gas_used |\n");
    out.push_str("| --- | --- | ---: |\n");
    if let Some(matrix) = summary["runtime_overheads"]["matrix"].as_array() {
        for row in matrix {
            if row["executable"].as_bool() == Some(true) {
                out.push_str(&format!(
                    "| `{}` | `{}` | `{}` |\n",
                    row["benchmark"].as_str().unwrap_or("unknown"),
                    row["backend"].as_str().unwrap_or("unknown"),
                    row["gas_used"]
                        .as_u64()
                        .map(|gas| gas.to_string())
                        .unwrap_or_else(|| "-".into()),
                ));
            }
        }
    }

    out.push('\n');
    out.push_str("## Rejected Backends\n\n");
    out.push_str(
        "Compile/admission failures recorded as explicit rows with reasons, not \
        missing data.\n\n",
    );
    out.push_str("| Benchmark | Backend | Reason |\n");
    out.push_str("| --- | --- | --- |\n");
    if let Some(matrix) = summary["runtime_overheads"]["matrix"].as_array() {
        for row in matrix {
            if row["rejected"].as_bool() == Some(true) {
                out.push_str(&format!(
                    "| `{}` | `{}` | {} |\n",
                    row["benchmark"].as_str().unwrap_or("unknown"),
                    row["backend"].as_str().unwrap_or("unknown"),
                    markdown_escape(row["error"].as_str().unwrap_or("rejected")),
                ));
            }
        }
    }

    Ok(out)
}

fn markdown_escape(value: &str) -> String {
    value.replace('|', "\\|")
}

fn report_artifact_budget_bytes(report: &JsonValue, field: &str) -> Option<u64> {
    report["artifact_configuration"][field].as_u64()
}

fn scenario_checked_json_bytes(scenario: &JsonValue) -> Option<u64> {
    [
        "theorem_input_json_bytes",
        "certificate_json_bytes",
        "witness_family_json_bytes",
        "heavy_artifact_json_bytes",
    ]
    .into_iter()
    .find_map(|field| scenario[field].as_u64())
}

fn scenario_estimated_json_bytes(scenario: &JsonValue, estimate_field: &str) -> Option<u64> {
    scenario[estimate_field]
        .as_u64()
        .or_else(|| scenario["size_estimate"]["estimated_family_json_bytes"].as_u64())
        .or_else(|| scenario_checked_json_bytes(scenario))
}

fn collect_proof_artifact_budget_scenario(
    scenarios: &mut Vec<JsonValue>,
    report: &str,
    artifact_kind: &str,
    scenario: &JsonValue,
    estimate_field: &str,
    compact_budget_bytes: u64,
    heavy_budget_bytes: u64,
) {
    let validation_status = scenario["validation_status"].as_str().unwrap_or("accepted");
    let estimated_json_bytes =
        scenario_estimated_json_bytes(scenario, estimate_field).unwrap_or_default();
    let checked_json_bytes = scenario_checked_json_bytes(scenario).unwrap_or_default();
    let exceeds_compact_budget = estimated_json_bytes > compact_budget_bytes;
    let selected_budget_bytes = if validation_status == "accepted_heavy_artifact" {
        heavy_budget_bytes
    } else {
        compact_budget_bytes
    };
    let checked_artifact_within_selected_budget = checked_json_bytes <= selected_budget_bytes;
    let theorem_input_within_compact_budget = scenario["theorem_input_json_bytes"]
        .as_u64()
        .map(|bytes| bytes <= compact_budget_bytes)
        .unwrap_or(true);
    let optional_heavy_artifact = validation_status == "accepted_heavy_artifact"
        && estimated_json_bytes <= heavy_budget_bytes;
    let oversized_has_non_enumerating_theorem_route = !exceeds_compact_budget
        || validation_status == "accepted_compact_theorem_input"
        || optional_heavy_artifact;
    let proof_grade_accepted = scenario["proof_grade_accepted"]
        .as_bool()
        .or_else(|| scenario["lean_validated"].as_bool())
        .or_else(|| scenario["accepted"].as_bool())
        .unwrap_or(false);

    scenarios.push(json!({
        "report": report,
        "artifact_kind": artifact_kind,
        "scenario": scenario["scenario"].as_str().unwrap_or("unknown"),
        "validation_status": validation_status,
        "estimated_json_bytes": estimated_json_bytes,
        "checked_json_bytes": checked_json_bytes,
        "compact_budget_bytes": compact_budget_bytes,
        "heavy_budget_bytes": heavy_budget_bytes,
        "exceeds_compact_budget": exceeds_compact_budget,
        "checked_artifact_within_selected_budget":
            checked_artifact_within_selected_budget,
        "theorem_input_within_compact_budget": theorem_input_within_compact_budget,
        "oversized_has_non_enumerating_theorem_route":
            oversized_has_non_enumerating_theorem_route,
        "requires_enumerated_witness_family_for_theorem":
            exceeds_compact_budget && !oversized_has_non_enumerating_theorem_route,
        "proof_grade_accepted": proof_grade_accepted,
        "accepted": scenario["accepted"].as_bool().unwrap_or(false),
    }));
}

fn proof_artifact_size_budget_summary(
    fresh_coin_validation: &JsonValue,
    canonical_pathoram_pair_validation: &JsonValue,
) -> JsonValue {
    let compact_budget_bytes =
        report_artifact_budget_bytes(fresh_coin_validation, "compact_budget_bytes")
            .or_else(|| {
                report_artifact_budget_bytes(
                    canonical_pathoram_pair_validation,
                    "compact_budget_bytes",
                )
            })
            .unwrap_or(DEFAULT_CANONICAL_CERT_BUDGET_BYTES);
    let heavy_budget_bytes =
        report_artifact_budget_bytes(fresh_coin_validation, "heavy_budget_bytes")
            .or_else(|| {
                report_artifact_budget_bytes(
                    canonical_pathoram_pair_validation,
                    "heavy_budget_bytes",
                )
            })
            .unwrap_or(DEFAULT_HEAVY_ARTIFACT_BUDGET_BYTES);

    let mut scenarios = Vec::new();
    if let Some(rows) = fresh_coin_validation["scenarios"].as_array() {
        for scenario in rows {
            collect_proof_artifact_budget_scenario(
                &mut scenarios,
                "fresh_coin_validation",
                "canonical_fresh_coin_family",
                scenario,
                "estimated_family_json_bytes",
                compact_budget_bytes,
                heavy_budget_bytes,
            );
        }
    }
    if let Some(rows) = canonical_pathoram_pair_validation["scenarios"].as_array() {
        for scenario in rows {
            collect_proof_artifact_budget_scenario(
                &mut scenarios,
                "canonical_pathoram_pair_validation",
                "canonical_pathoram_pair_certificate",
                scenario,
                "estimated_certificate_json_bytes",
                compact_budget_bytes,
                heavy_budget_bytes,
            );
        }
    }

    let scenario_count = scenarios.len();
    let oversized_estimate_count = scenarios
        .iter()
        .filter(|row| row["exceeds_compact_budget"].as_bool() == Some(true))
        .count();
    let max_checked_json_bytes = scenarios
        .iter()
        .filter_map(|row| row["checked_json_bytes"].as_u64())
        .max()
        .unwrap_or_default();
    let max_estimated_json_bytes = scenarios
        .iter()
        .filter_map(|row| row["estimated_json_bytes"].as_u64())
        .max()
        .unwrap_or_default();
    let all_checked_artifacts_within_selected_budget = scenarios.iter().all(|row| {
        row["checked_artifact_within_selected_budget"]
            .as_bool()
            .unwrap_or(false)
    });
    let all_theorem_inputs_within_compact_budget = scenarios.iter().all(|row| {
        row["theorem_input_within_compact_budget"]
            .as_bool()
            .unwrap_or(false)
    });
    let all_oversized_estimates_have_non_enumerating_route = scenarios.iter().all(|row| {
        row["oversized_has_non_enumerating_theorem_route"]
            .as_bool()
            .unwrap_or(false)
    });
    let theorem_facing_large_artifacts_require_enumeration = scenarios.iter().any(|row| {
        row["requires_enumerated_witness_family_for_theorem"]
            .as_bool()
            .unwrap_or(false)
    });
    let all_proof_grade_accepted = scenarios
        .iter()
        .all(|row| row["proof_grade_accepted"].as_bool().unwrap_or(false));
    let accepted = scenario_count > 0
        && all_checked_artifacts_within_selected_budget
        && all_theorem_inputs_within_compact_budget
        && all_oversized_estimates_have_non_enumerating_route
        && !theorem_facing_large_artifacts_require_enumeration
        && all_proof_grade_accepted;

    json!({
        "compact_budget_bytes": compact_budget_bytes,
        "heavy_budget_bytes": heavy_budget_bytes,
        "scenario_count": scenario_count,
        "oversized_estimate_count": oversized_estimate_count,
        "max_checked_json_bytes": max_checked_json_bytes,
        "max_estimated_json_bytes": max_estimated_json_bytes,
        "all_checked_artifacts_within_selected_budget":
            all_checked_artifacts_within_selected_budget,
        "all_theorem_inputs_within_compact_budget":
            all_theorem_inputs_within_compact_budget,
        "all_oversized_estimates_have_non_enumerating_route":
            all_oversized_estimates_have_non_enumerating_route,
        "theorem_facing_large_artifacts_require_enumeration":
            theorem_facing_large_artifacts_require_enumeration,
        "all_proof_grade_accepted": all_proof_grade_accepted,
        "accepted": accepted,
        "scenarios": scenarios,
    })
}

