fn run_runtime_confidential_statement_trace_bridge_boundary_validation() -> Result<JsonValue> {
    let checker =
        lean_proofgrade_runtime_confidential_statement_trace_bridge_boundary_checker_path()?;
    let boundary = runtime_implementation_confidential_statement_trace_bridge_boundary_artifact()?;
    let interface = &boundary.implementation_interface;
    let state_bytes = interface.state_source.len();
    let kernel_runtime_bytes = interface.kernel_runtime_source.len();
    let kernel_slot_support_bytes = interface.kernel_slot_support_source.len();
    let generated_kernel_machine_bytes = interface.generated_kernel_machine_source.len();
    let generated_object_helpers_bytes = interface.generated_object_helpers_source.len();
    let generated_oram_codecs_bytes = interface.generated_oram_codecs_source.len();
    let confidential_kernel_bytes = interface.confidential_kernel_source.len();
    let generated_confidential_kernel_bytes = interface.generated_confidential_kernel_source.len();
    let trace_bytes = interface.trace_source.len();
    let confidential_core_bytes = interface.confidential_core_source.len();
    let trusted_kernel_bytes = interface.trusted_kernel_source.len();
    let allocator_bytes = interface.allocator_source.len();
    let (boundary_path, artifact_json_bytes) = write_temp_json(
        "runtime-confidential-statement-trace-bridge-boundary",
        &boundary,
    )?;
    let output = Command::new(&checker).arg(&boundary_path).output()?;
    let _ = fs::remove_file(&boundary_path);
    if !output.status.success() {
        return Err(anyhow!(
            "Lean runtime confidential statement-trace bridge boundary validation failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(json!({
        "checker": display_report_path(&checker),
        "source_files": existing_report_paths(&[
            repo_root().join("runtime/uo-evm/src/state.rs"),
            repo_root().join("runtime/uo-kernel-runtime/src/lib.rs"),
            repo_root().join("runtime/uo-kernel-runtime/src/generated_slot_support.rs"),
            repo_root().join("runtime/uo-kernel-runtime/src/generated_machine.rs"),
            repo_root().join("runtime/uo-evm/src/generated_object_helpers.rs"),
            repo_root().join("runtime/uo-evm/src/generated_oram_codecs.rs"),
            repo_root().join("crates/uo-core/src/confidential_kernel.rs"),
            repo_root().join("crates/uo-core/src/generated_confidential_kernel.rs"),
            repo_root().join("crates/uo-core/src/trace.rs"),
            repo_root().join("crates/uo-core/src/confidential_core.rs"),
            repo_root().join("crates/uo-core/src/trusted_kernel.rs"),
            repo_root().join("runtime/uo-allocator/src/lib.rs"),
        ]),
        "source_bytes": {
            "state": state_bytes,
            "kernel_runtime": kernel_runtime_bytes,
            "kernel_slot_support": kernel_slot_support_bytes,
            "generated_kernel_machine": generated_kernel_machine_bytes,
            "generated_object_helpers": generated_object_helpers_bytes,
            "generated_oram_codecs": generated_oram_codecs_bytes,
            "confidential_kernel": confidential_kernel_bytes,
            "generated_confidential_kernel": generated_confidential_kernel_bytes,
            "trace": trace_bytes,
            "confidential_core": confidential_core_bytes,
            "trusted_kernel": trusted_kernel_bytes,
            "allocator": allocator_bytes,
        },
        "confidential_statement_trace_bridge_boundary_theorem_checked": true,
        "artifact_json_bytes": artifact_json_bytes,
        "lean_checker_kind": "runtime confidential statement-trace bridge boundary",
        "lean_checker_input":
            "source-backed runtime confidential statement-trace bridge boundary",
        "lean_stdout": String::from_utf8_lossy(&output.stdout).trim(),
        "accepted": true,
    }))
}

