fn run_runtime_implementation_kernel_machine_confinement_boundary_validation(
    suite: &BTreeMap<&'static str, BenchArtifacts>,
) -> Result<JsonValue> {
    let checker =
        lean_proofgrade_runtime_implementation_kernel_machine_confinement_boundary_checker_path()?;
    let implementation_interface = runtime_implementation_interface_artifact()?;
    let source_paths = runtime_implementation_interface_source_paths();
    let oram_write_batch_iteration_is_checked = implementation_interface
        .oram_source
        .contains("pub(crate) fn for_each_write<F>(&self, mut visitor: F) -> Result<()>")
        && implementation_interface
            .oram_source
            .contains("ORAM write batch public length {} exceeds capacity {}")
        && implementation_interface
            .oram_source
            .contains("self.writes.get(index).ok_or_else")
        && implementation_interface
            .oram_source
            .contains("ORAM write batch public prefix index {} missing despite length guard")
        && implementation_interface
            .oram_source
            .contains("ORAM write batch missing populated public prefix entry {index}")
        && implementation_interface
            .oram_source
            .contains("visitor(write)?;")
        && implementation_interface
            .objects_source
            .contains("physical_writes.for_each_write(|write| {")
        && implementation_interface
            .objects_source
            .contains("writes.for_each_write(|write| {")
        && !implementation_interface
            .oram_source
            .contains("self.writes[index]")
        && !implementation_interface
            .oram_source
            .contains("filter_map(Option::as_ref)");
    let engine_production_source = strip_cfg_test_items(&implementation_interface.engine_source);
    let shell_production_source = strip_cfg_test_items(&implementation_interface.shell_source);
    let state_production_source = strip_cfg_test_items(&implementation_interface.state_source);
    let objects_production_source = strip_cfg_test_items(&implementation_interface.objects_source);
    let oram_production_source = strip_cfg_test_items(&implementation_interface.oram_source);
    let panic_style_needles = [
        "expect(",
        "unwrap(",
        "panic!",
        "assert!(",
        "assert_eq!(",
        "debug_assert!(",
        "debug_assert_eq!(",
    ];
    let handwritten_runtime_production_avoids_panic_style_control_flow = [
        engine_production_source.as_str(),
        shell_production_source.as_str(),
        state_production_source.as_str(),
        objects_production_source.as_str(),
        oram_production_source.as_str(),
    ]
    .iter()
    .all(|source| {
        panic_style_needles
            .iter()
            .all(|needle| !source.contains(needle))
    });
    let runtime_interface_production_avoids_panic_style_control_flow = [
        implementation_interface.runtime_evm_lib_source.as_str(),
        engine_production_source.as_str(),
        implementation_interface.runtime_module_source.as_str(),
        implementation_interface.fresh_coins_source.as_str(),
        implementation_interface.controller_source.as_str(),
        shell_production_source.as_str(),
        state_production_source.as_str(),
        implementation_interface.kernel_runtime_source.as_str(),
        implementation_interface.kernel_slot_support_source.as_str(),
        implementation_interface
            .generated_kernel_machine_source
            .as_str(),
        implementation_interface
            .generated_object_helpers_source
            .as_str(),
        implementation_interface
            .generated_oram_codecs_source
            .as_str(),
        objects_production_source.as_str(),
        oram_production_source.as_str(),
        implementation_interface.theorem_source.as_str(),
        implementation_interface.confidential_kernel_source.as_str(),
        implementation_interface
            .generated_confidential_kernel_source
            .as_str(),
        implementation_interface.trace_source.as_str(),
        implementation_interface.confidential_core_source.as_str(),
        implementation_interface.trusted_kernel_source.as_str(),
        implementation_interface.core_lib_source.as_str(),
        implementation_interface.precompiles_source.as_str(),
        implementation_interface.allocator_source.as_str(),
        implementation_interface.store_lib_source.as_str(),
        implementation_interface.store_codec_source.as_str(),
        implementation_interface
            .generated_store_codec_source
            .as_str(),
        implementation_interface
            .generated_store_surface_source
            .as_str(),
        implementation_interface
            .generated_store_helpers_source
            .as_str(),
        implementation_interface.store_store_source.as_str(),
        implementation_interface.generated_value_ops_source.as_str(),
        implementation_interface.types_source.as_str(),
    ]
    .iter()
    .all(|source| {
        let production = strip_cfg_test_items(source);
        panic_style_needles
            .iter()
            .all(|needle| !production.contains(needle))
    });
    let (scenarios, excluded_scenarios) =
        collect_proofgrade_runtime_validation_scenarios(suite, |name, artifact, setup, target| {
            validate_runtime_implementation_kernel_machine_confinement_boundary_case(
                name,
                artifact,
                setup,
                target,
                &checker,
                &implementation_interface,
            )
        })?;

    Ok(json!({
        "checker": display_report_path(&checker),
        "source_files": existing_report_paths(&source_paths),
        "implementation_interface_boundary_checks": {
            "oram_write_batch_iteration_is_checked":
                oram_write_batch_iteration_is_checked,
            "handwritten_runtime_production_avoids_panic_style_control_flow":
                handwritten_runtime_production_avoids_panic_style_control_flow,
            "runtime_interface_production_avoids_panic_style_control_flow":
                runtime_interface_production_avoids_panic_style_control_flow,
        },
        "scenario_count": scenarios.len(),
        "scenarios": scenarios,
        "excluded_scenarios": excluded_scenarios,
    }))
}

