fn validate_runtime_implementation_public_bridge_observer_refinement_boundary_case(
    name: &'static str,
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    target: &CallSpec,
    checker: &Path,
    implementation_interface: &ImportedRuntimeImplementationInterface,
) -> Result<JsonValue> {
    let trace = run_target_call(artifact, setup, target.entrypoint, target.args.clone())?;
    let runtime_witness = trace.runtime_refinement_witness()?;
    let exact_kernel_witness =
        exact_confidential_kernel_witness(&trace, artifact, target.entrypoint)?;
    if runtime_witness.kernel_witness() != exact_kernel_witness.as_ref() {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the exact kernel witness",
            name
        ));
    }
    let exact_runtime_kernel_refinement_witness =
        trace.exact_runtime_kernel_refinement_witness()?;
    if runtime_witness.runtime_kernel_refinement_witness()
        != Some(&exact_runtime_kernel_refinement_witness)
    {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the runtime phase witness",
            name
        ));
    }
    let runtime_kernel_machine_finish_witness =
        trace.exact_runtime_kernel_machine_finish_witness().map_err(|err| {
            anyhow!(
                "execution trace for {} did not expose an exact runtime kernel machine finish witness: {}",
                name,
                err
            )
        })?;
    let projected_finish_bundle = runtime_kernel_machine_finish_witness.projected_finish_bundle();
    let finish_bundle = trace.exact_runtime_kernel_finish_bundle().map_err(|err| {
        anyhow!(
            "execution trace for {} did not expose an exact runtime kernel finish bundle: {}",
            name,
            err
        )
    })?;
    if projected_finish_bundle != finish_bundle {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} does not preserve the exact runtime kernel finish bundle",
            name
        ));
    }
    let bundle = trace.runtime_confidential_core_kernel_finish_slot_bundle(artifact)?;
    let confidential_slot_program = bundle.confidential_slot_program().clone();
    if confidential_slot_program
        .expected_runtime_step_witnesses()
        .as_ref()
        != finish_bundle.kernel_steps()
    {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} does not preserve the exact confidential slot schedule",
            name
        ));
    }
    if bundle.opcode_trace() != confidential_slot_program.statement_trace().as_ref() {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} does not preserve the exact confidential statement trace",
            name
        ));
    }
    let machine_finish_schedule_consumed = match finish_bundle.expected_kernel_steps() {
        Some(steps) => {
            runtime_kernel_machine_finish_witness.expected_kernel_step_index() == steps.len()
        }
        None => runtime_kernel_machine_finish_witness.expected_kernel_step_index() == 0,
    };
    if !machine_finish_schedule_consumed {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} does not consume the exact expected kernel schedule",
            name
        ));
    }
    let machine_finish_kernel_step_budget_respected = finish_bundle.kernel_steps().len()
        <= runtime_kernel_machine_finish_witness.max_kernel_ops();
    if !machine_finish_kernel_step_budget_respected {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} exceeds the runtime kernel machine step budget",
            name
        ));
    }
    let machine_finish_runtime_phase_budget_respected =
        exact_runtime_kernel_refinement_witness.events().len()
            <= runtime_kernel_machine_finish_witness.max_runtime_phase_event_count();
    if !machine_finish_runtime_phase_budget_respected {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} exceeds the runtime phase event budget",
            name
        ));
    }
    let slot_semantics_exact = finish_bundle.expected_kernel_steps()
        == Some(
            confidential_slot_program
                .expected_runtime_step_witnesses()
                .as_ref(),
        )
        && finish_bundle.kernel_steps()
            == confidential_slot_program
                .expected_runtime_step_witnesses()
                .as_ref();
    if !slot_semantics_exact {
        return Err(anyhow!(
            "runtime implementation public bridge observer-refinement boundary for {} does not preserve exact slot semantics",
            name
        ));
    }
    let boundary = ImportedRuntimeImplementationPublicBridgeObserverRefinementBoundary {
        implementation_interface: implementation_interface.clone(),
        runtime_kernel_machine_finish_witness,
        confidential_slot_program: confidential_slot_program.clone(),
        opcode_trace: bundle.opcode_trace().to_vec().into_boxed_slice(),
    };
    let machine_finish_witness_json_bytes =
        serde_json::to_vec(&boundary.runtime_kernel_machine_finish_witness)?.len();
    let confidential_slot_program_json_bytes =
        serde_json::to_vec(&boundary.confidential_slot_program)?.len();
    let opcode_trace_json_bytes = serde_json::to_vec(&boundary.opcode_trace)?.len();
    let (boundary_path, boundary_json_bytes) = write_temp_json(name, &boundary)?;
    let output = Command::new(checker).arg(&boundary_path).output()?;
    if !output.status.success() {
        return Err(anyhow!(
            "Lean runtime implementation public bridge observer-refinement boundary validation failed for {}: {} (artifact preserved at {})",
            name,
            String::from_utf8_lossy(&output.stderr).trim(),
            boundary_path.display()
        ));
    }
    let _ = fs::remove_file(&boundary_path);
    Ok(json!({
        "scenario": name,
        "entrypoint": target.entrypoint,
        "setup_calls": setup.len(),
        "gas_used": trace.gas_used,
        "boundary_events": runtime_witness.boundary_schedule().len(),
        "kernel_witness": kernel_witness_summary(exact_kernel_witness.as_ref()),
        "runtime_kernel_refinement_witness": runtime_kernel_refinement_witness_summary(
            runtime_witness.runtime_kernel_refinement_witness(),
            exact_kernel_witness.as_ref(),
        ),
        "runtime_kernel_machine_finish_witness": {
            "entrypoint_id": finish_bundle.entrypoint_id(),
            "expected_kernel_step_count": finish_bundle
                .expected_kernel_steps()
                .map_or(0, |steps| steps.len()),
            "emitted_kernel_step_count": finish_bundle.kernel_steps().len(),
            "expected_kernel_step_index":
                boundary.runtime_kernel_machine_finish_witness.expected_kernel_step_index(),
            "max_kernel_ops": boundary.runtime_kernel_machine_finish_witness.max_kernel_ops(),
            "max_runtime_phase_event_count":
                boundary.runtime_kernel_machine_finish_witness.max_runtime_phase_event_count(),
            "runtime_phase_prefix_event_count":
                finish_bundle.runtime_phase_events_before_finish().len(),
            "runtime_phase_event_count":
                exact_runtime_kernel_refinement_witness.events().len(),
            "public_object_universe": finish_bundle.public_object_ids(),
            "resource_event_count": finish_bundle.resource_events().event_count(),
        },
        "public_bridge_observer_boundary": {
            "entrypoint_id": confidential_slot_program.entrypoint_id.as_str(),
            "param_count": confidential_slot_program.param_count,
            "secret_arg_count": confidential_slot_program.secret_args.len(),
            "slot_count": confidential_slot_program.slot_count,
            "statement_count": confidential_slot_program.body.len(),
            "expected_runtime_step_count":
                confidential_slot_program.expected_runtime_steps().len(),
            "statement_trace_count": confidential_slot_program.statement_trace().len(),
            "public_bridge_boundary_theorem_checked": true,
            "residual_helper_shell_boundary_theorem_checked": true,
            "handwritten_runtime_public_only_theorem_checked": true,
            "paper_public_bridge_observer_refinement_boundary_theorem_checked": true,
        },
        "machine_finish_schedule_consumed": machine_finish_schedule_consumed,
        "machine_finish_kernel_step_budget_respected":
            machine_finish_kernel_step_budget_respected,
        "machine_finish_runtime_phase_budget_respected":
            machine_finish_runtime_phase_budget_respected,
        "slot_semantics_exact": slot_semantics_exact,
        "implementation_interface_source_bytes":
            runtime_implementation_interface_source_bytes(implementation_interface),
        "machine_finish_witness_json_bytes": machine_finish_witness_json_bytes,
        "confidential_slot_program_json_bytes": confidential_slot_program_json_bytes,
        "opcode_trace_json_bytes": opcode_trace_json_bytes,
        "boundary_json_bytes": boundary_json_bytes,
        "lean_checker_kind":
            "runtime implementation public bridge observer-refinement boundary",
        "lean_checker_input":
            "source-backed runtime public bridge plus public-only handwritten shell claim and native machine-finish witness / exact opcode trace",
        "lean_stdout": String::from_utf8_lossy(&output.stdout).trim(),
        "accepted": true,
    }))
}

