    let finish_shell_boundary_bundle = bundle.runtime_shell_boundary_bundle().map_err(|err| {
        anyhow!("reconstructing validated shell-boundary bundle for {name}: {err}")
    })?;
    if Some(finish_shell_boundary_bundle.kernel_witness()) != exact_kernel_witness.as_ref() {
        return Err(anyhow!(
            "runtime implementation confidential statement-trace bridge refinement boundary for {} does not preserve the exact kernel witness",
            name
        ));
    }
    if trace.exact_runtime_kernel_refinement_witness()?
        != *finish_shell_boundary_bundle.runtime_kernel_refinement_witness()
    {
        return Err(anyhow!(
            "runtime implementation confidential statement-trace bridge refinement boundary for {} does not preserve the runtime phase witness",
            name
        ));
    }
    let confidential_slot_program = bundle.confidential_slot_program();
    if confidential_slot_program
        .expected_runtime_step_witnesses()
        .as_ref()
        != finish_bundle.kernel_steps()
    {
        return Err(anyhow!(
            "runtime implementation confidential statement-trace bridge refinement boundary for {} does not preserve the exact confidential slot schedule",
            name
        ));
    }
    let confidential_slot_program_entrypoint =
        confidential_slot_program.entrypoint_id.as_str().to_owned();
    let confidential_slot_program_param_count = confidential_slot_program.param_count;
    let confidential_slot_program_secret_arg_count = confidential_slot_program.secret_args.len();
    let confidential_slot_program_slot_count = confidential_slot_program.slot_count;
    let confidential_slot_program_statement_count = confidential_slot_program.body.len();
    let confidential_slot_program_expected_runtime_step_count =
        confidential_slot_program.expected_runtime_steps().len();
    let confidential_slot_program_statement_trace_count =
        confidential_slot_program.statement_trace().len();
    let matches_runtime_entrypoint = bundle.program_matches_runtime_entrypoint();
    let boundary =
        ImportedRuntimeImplementationConfidentialStatementTraceBridgeRefinementBoundary {
            implementation_interface: implementation_interface.clone(),
            runtime_confidential_core_kernel_finish_slot_bundle: bundle,
        };
    let kernel_finish_slot_bundle_json_bytes =
        serde_json::to_vec(&boundary.runtime_confidential_core_kernel_finish_slot_bundle)?.len();
    let (boundary_path, boundary_json_bytes) = write_temp_json(name, &boundary)?;
    let output = Command::new(checker).arg(&boundary_path).output()?;
