fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("workspace root should exist")
}

fn extract_rust_enum_variants(source: &str, enum_name: &str) -> Result<Vec<String>> {
    let marker = format!("pub enum {enum_name} {{");
    let start = source
        .find(&marker)
        .ok_or_else(|| anyhow!("Rust enum `{enum_name}` not found"))?
        + marker.len();
    let mut brace_depth = 1usize;
    let mut paren_depth = 0usize;
    let mut bracket_depth = 0usize;
    let mut current_variant = String::new();
    let mut variants = Vec::new();
    for ch in source[start..].chars() {
        match ch {
            '{' => {
                brace_depth += 1;
                current_variant.push(ch);
            }
            '}' => {
                brace_depth = brace_depth
                    .checked_sub(1)
                    .ok_or_else(|| anyhow!("Rust enum `{enum_name}` has unbalanced braces"))?;
                if brace_depth == 0 {
                    let trimmed = current_variant.trim();
                    if !trimmed.is_empty() {
                        variants.push(trimmed.to_string());
                    }
                    break;
                }
                current_variant.push(ch);
            }
            '(' => {
                paren_depth += 1;
                current_variant.push(ch);
            }
            ')' => {
                paren_depth = paren_depth
                    .checked_sub(1)
                    .ok_or_else(|| anyhow!("Rust enum `{enum_name}` has unbalanced parentheses"))?;
                current_variant.push(ch);
            }
            '[' => {
                bracket_depth += 1;
                current_variant.push(ch);
            }
            ']' => {
                bracket_depth = bracket_depth
                    .checked_sub(1)
                    .ok_or_else(|| anyhow!("Rust enum `{enum_name}` has unbalanced brackets"))?;
                current_variant.push(ch);
            }
            ',' if brace_depth == 1 && paren_depth == 0 && bracket_depth == 0 => {
                let trimmed = current_variant.trim();
                if !trimmed.is_empty() {
                    variants.push(trimmed.to_string());
                }
                current_variant.clear();
            }
            _ => current_variant.push(ch),
        }
    }
    let variants = variants
        .into_iter()
        .filter_map(|variant| {
            let trimmed = variant.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with("//") {
                None
            } else {
                trimmed
                    .split(|ch: char| ch.is_whitespace() || ch == '{' || ch == '(')
                    .next()
                    .map(str::to_string)
            }
        })
        .collect::<Vec<_>>();
    if variants.is_empty() {
        Err(anyhow!("Rust enum `{enum_name}` has no parsed variants"))
    } else {
        Ok(variants)
    }
}

fn extract_rust_struct_fields(source: &str, struct_name: &str) -> Result<Vec<String>> {
    let marker = format!("pub struct {struct_name} {{");
    let private_marker = format!("struct {struct_name} {{");
    let start = if let Some(start) = source.find(&marker) {
        start + marker.len()
    } else if let Some(start) = source.find(&private_marker) {
        start + private_marker.len()
    } else {
        return Err(anyhow!("Rust struct `{struct_name}` not found"));
    };
    let remainder = &source[start..];
    let end = remainder
        .find('}')
        .ok_or_else(|| anyhow!("Rust struct `{struct_name}` missing closing brace"))?;
    let body = &remainder[..end];
    let fields = body
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with("//") {
                None
            } else {
                let field_line = trimmed
                    .strip_prefix("pub(crate) ")
                    .or_else(|| trimmed.strip_prefix("pub(super) "))
                    .or_else(|| trimmed.strip_prefix("pub "))
                    .unwrap_or(trimmed);
                if !field_line.contains(':') {
                    None
                } else {
                    field_line
                        .split(':')
                        .next()
                        .map(str::trim)
                        .map(str::to_string)
                }
            }
        })
        .collect::<Vec<_>>();
    if fields.is_empty() {
        Err(anyhow!("Rust struct `{struct_name}` has no parsed fields"))
    } else {
        Ok(fields)
    }
}

fn rust_struct_derives_without_clone(source: &str, struct_name: &str, derive_args: &str) -> bool {
    let markers = [
        format!("pub struct {struct_name} {{"),
        format!("pub(crate) struct {struct_name} {{"),
        format!("struct {struct_name} {{"),
    ];
    let Some(start) = markers
        .iter()
        .filter_map(|marker| source.find(marker))
        .min()
    else {
        return false;
    };
    let derive_attr = format!("#[derive({derive_args})]");
    let attr_lines = source[..start]
        .lines()
        .rev()
        .map(str::trim)
        .take_while(|line| line.starts_with("#["))
        .collect::<Vec<_>>();
    attr_lines.iter().any(|line| *line == derive_attr)
        && !attr_lines.iter().any(|line| line.contains("Clone"))
}

fn extract_rust_impl_block(source: &str, type_name: &str) -> Result<String> {
    let marker = format!("impl {type_name} {{");
    let start = source
        .find(&marker)
        .ok_or_else(|| anyhow!("Rust impl for `{type_name}` not found"))?;
    let body_start = start + marker.len();
    let bytes = source.as_bytes();
    let mut depth = 1usize;
    let mut cursor = body_start;

    while cursor < bytes.len() && depth > 0 {
        match bytes[cursor] {
            b'{' => depth += 1,
            b'}' => {
                depth = depth
                    .checked_sub(1)
                    .ok_or_else(|| anyhow!("Rust impl for `{type_name}` has unbalanced braces"))?
            }
            _ => {}
        }
        cursor += 1;
    }

    if depth != 0 {
        return Err(anyhow!("Rust impl for `{type_name}` missing closing brace"));
    }

    Ok(source[start..cursor].to_string())
}

fn rust_enum_has_serde_snake_case(source: &str, enum_name: &str) -> bool {
    let marker = format!("pub enum {enum_name} {{");
    source.find(&marker).is_some_and(|start| {
        source[start.saturating_sub(256)..start].contains("rename_all = \"snake_case\"")
    })
}

fn extract_lean_string_list(source: &str, def_name: &str) -> Result<Vec<String>> {
    let marker = format!("def {def_name} : List String :=");
    let start = source
        .find(&marker)
        .ok_or_else(|| anyhow!("Lean string list `{def_name}` not found"))?
        + marker.len();
    let remainder = &source[start..];
    let end = remainder
        .find(']')
        .ok_or_else(|| anyhow!("Lean string list `{def_name}` missing closing bracket"))?;
    let body = &remainder[..=end];
    let mut strings = Vec::new();
    let mut current = String::new();
    let mut in_string = false;
    let mut escape = false;
    for ch in body.chars() {
        if in_string {
            if escape {
                current.push(ch);
                escape = false;
            } else if ch == '\\' {
                escape = true;
            } else if ch == '"' {
                strings.push(current.clone());
                current.clear();
                in_string = false;
            } else {
                current.push(ch);
            }
        } else if ch == '"' {
            in_string = true;
        }
    }
    if strings.is_empty() {
        Err(anyhow!(
            "Lean string list `{def_name}` has no parsed entries"
        ))
    } else {
        Ok(strings)
    }
}

fn extract_lean_bool_list(source: &str, def_name: &str) -> Result<Vec<bool>> {
    let marker = format!("def {def_name} : List Bool :=");
    let start = source
        .find(&marker)
        .ok_or_else(|| anyhow!("Lean bool list `{def_name}` not found"))?
        + marker.len();
    let remainder = &source[start..];
    let end = remainder
        .find(']')
        .ok_or_else(|| anyhow!("Lean bool list `{def_name}` missing closing bracket"))?;
    let body = &remainder[..=end];
    let mut bools = Vec::new();
    for token in body
        .split(|ch: char| ch == '[' || ch == ']' || ch == ',' || ch.is_whitespace())
        .filter(|token| !token.is_empty())
    {
        match token {
            "true" => bools.push(true),
            "false" => bools.push(false),
            other => {
                return Err(anyhow!(
                    "Lean bool list `{def_name}` contains unexpected token `{other}`"
                ))
            }
        }
    }
    if bools.is_empty() {
        Err(anyhow!("Lean bool list `{def_name}` has no parsed entries"))
    } else {
        Ok(bools)
    }
}

fn to_snake_case(name: &str) -> String {
    let mut out = String::new();
    for (idx, ch) in name.chars().enumerate() {
        if ch.is_ascii_uppercase() {
            if idx != 0 {
                out.push('_');
            }
            out.push(ch.to_ascii_lowercase());
        } else {
            out.push(ch);
        }
    }
    out
}

fn collect_rust_source_files(root: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
    for entry in fs::read_dir(root).with_context(|| format!("reading {}", root.display()))? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_rust_source_files(&path, files)?;
        } else if path.extension().is_some_and(|ext| ext == "rs") {
            files.push(path);
        }
    }
    Ok(())
}

fn collect_lean_source_files(root: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
    for entry in fs::read_dir(root).with_context(|| format!("reading {}", root.display()))? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_lean_source_files(&path, files)?;
        } else if path.extension().is_some_and(|ext| ext == "lean") {
            files.push(path);
        }
    }
    Ok(())
}

/// Whether a deployment's seed stays out of call traces. Only a seeded (test
/// or diagnostics) deployment has one, and the engine keeps it as the replay
/// tag of the instance's traces. A deployment from OS randomness has none,
/// and neither the runtime module, which deploys the state from the master
/// secret, nor the theorem bridge, which builds the trace, sees a seed.
fn check_deployment_seed_stays_out_of_call_traces(
    engine_impl_source: &str,
    runtime_module_source: &str,
    theorem_source: &str,
) -> bool {
    engine_impl_source
        .contains("Self::deploy_internal(artifact, &master, freshness, None, storage)")
        && engine_impl_source.contains(
            "Self::deploy_internal(artifact, &master, freshness, Some(deploy_seed), storage)",
        )
        && engine_impl_source.contains("replay_seed: Option<u64>,")
        && engine_impl_source.contains("self.replay_seed,")
        && !engine_impl_source.contains("self.deploy_seed")
        && runtime_module_source.contains("replay_seed: Option<u64>,")
        && !runtime_module_source.contains("deploy_seed")
        && !theorem_source.contains("deploy_seed")
}

/// Whether a deployment's secrets derive from a master secret that production
/// draws from the operating system, with the freshness epoch, which is
/// public, drawn independently of it. A master secret that is a function of a
/// seed exists only in test and diagnostics builds, and no production source
/// seeds a generator from 64 bits.
fn check_runtime_secrets_derive_from_the_master_secret(
    engine_impl_source: &str,
    state_source: &str,
    objects_production_source: &str,
    secret_production_source: &str,
) -> bool {
    engine_impl_source.contains(
        "    pub fn deploy_with_storage(artifact: CompiledArtifact, storage: SharedStorage) -> Result<Self> {\n        let master = RuntimeMasterSecret::from_os_rng();\n        let freshness = RuntimeFreshnessState::from_os_rng();\n        Self::deploy_internal(artifact, &master, freshness, None, storage)\n    }",
    ) && engine_impl_source.contains(
        "    #[cfg(any(test, feature = \"diagnostics\"))]\n    pub fn deploy_with_seed_and_storage(\n        artifact: CompiledArtifact,\n        deploy_seed: u64,\n        storage: SharedStorage,\n    ) -> Result<Self> {\n        let master = RuntimeMasterSecret::from_diagnostic_seed(deploy_seed);",
    ) && engine_impl_source.contains(
        "    #[cfg(any(test, feature = \"diagnostics\"))]\n    pub fn restart_with_seed(\n        artifact: CompiledArtifact,\n        deploy_seed: u64,\n        storage: SharedStorage,\n        attested_rollback_counter: u64,\n    ) -> Result<Self> {\n        let master = RuntimeMasterSecret::from_diagnostic_seed(deploy_seed);",
    ) && engine_impl_source
        .matches("RuntimeMasterSecret::from_diagnostic_seed(")
        .count()
        == 2
        && engine_impl_source.matches("RuntimeMasterSecret::").count() == 3
        && !engine_impl_source.contains("seed_from_u64")
        && state_source.contains("let secret = master.object_secret(spec.id, &spec.name)?;")
        && state_source.contains("let mut object = RuntimeObject::instantiate(spec, &secret)?;")
        && objects_production_source.contains("let mut rng = secret.rng()?;")
        && objects_production_source
            .contains("let leaf_coin_seed = secret.path_oram_leaf_seed()?;")
        && !objects_production_source.contains("seed_from_u64")
        && secret_production_source.contains("const SECRET_BYTES: usize = 32;")
        && secret_production_source.contains(
            "    pub(crate) fn from_os_rng() -> Self {\n        let mut secret = [0u8; SECRET_BYTES];\n        OsRng.fill_bytes(&mut secret);\n        Self(secret)\n    }",
        )
        && secret_production_source.contains(
            "    #[cfg(any(test, feature = \"diagnostics\"))]\n    pub(crate) fn from_diagnostic_seed(seed: u64) -> Self {\n        Self(diagnostic_secret(DIAGNOSTIC_MASTER_SECRET_LABEL, seed))",
        )
        && secret_production_source.contains(
            "#[cfg(any(test, feature = \"diagnostics\"))]\nfn diagnostic_secret(label: &[u8], seed: u64) -> [u8; SECRET_BYTES] {",
        )
        && secret_production_source.matches("diagnostic_secret(").count() == 2
        && secret_production_source.contains("Hkdf::<Sha256>::from_prk(key)")
        // No secret type is cloned, compared or serialized by a derive.
        && !secret_production_source.contains("#[derive(")
        && !secret_production_source.contains("seed_from_u64")
}

/// Whether a sealed record's nonce is the count of the seals under its key.
/// The count is shared by every copy of the cipher and only grows, so a
/// nonce cannot repeat under a key, whether or not a call is committed. A
/// seal fails once the count is exhausted, and no nonce is drawn at random.
fn check_seal_nonces_come_from_the_seal_count(
    generated_store_surface_production_source: &str,
    generated_store_codec_source: &str,
) -> bool {
    generated_store_surface_production_source
        .contains("pub struct StoreCipher {\n    key: [u8; 32],\n    seals: Arc<AtomicU64>,\n    storage: Option<StorageHandle>,\n}")
        && generated_store_surface_production_source.contains(
            "        Self {\n            key,\n            seals: Arc::new(AtomicU64::new(0)),\n            storage: None,\n        }",
        )
        && generated_store_surface_production_source.contains(
            "        Self {\n            key: self.key,\n            seals: Arc::clone(&self.seals),\n            storage: self.storage.clone(),\n        }",
        )
        // The count is written where a cipher is made, where a seal reads
        // it and where a restart raises it, and nowhere else. A restart
        // cannot lower it.
        && generated_store_surface_production_source
            .matches("AtomicU64::new(")
            .count()
            == 1
        && generated_store_surface_production_source
            .matches("self.seals")
            .count()
            == 3
        && generated_store_surface_production_source.matches(".seals").count() == 4
        && generated_store_surface_production_source.contains(
            "    pub fn seal_count(&self) -> u64 {\n        self.seals.load(Ordering::SeqCst)\n    }",
        )
        && generated_store_surface_production_source.contains(
            "    pub fn resume_seal_count(&self, count: u64) {\n        self.seals.fetch_max(count, Ordering::SeqCst);\n    }",
        )
        && generated_store_surface_production_source.contains(
            "            .seals\n            .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |seals| {\n                seals.checked_add(1)\n            })\n            .ok()?;\n        Some(seal_nonce(counter))",
        )
        && generated_store_surface_production_source.contains(
            "    let Some(nonce_bytes) = cipher.next_seal_nonce() else {\n        return false;\n    };",
        )
        && generated_store_surface_production_source
            .matches("next_seal_nonce(")
            .count()
            == 2
        && generated_store_surface_production_source.contains("Nonce::from_slice(&nonce_bytes),")
        && !generated_store_surface_production_source.contains("fill_bytes(&mut nonce")
        && generated_store_surface_production_source
            .matches("fill_bytes(")
            .count()
            == 1
        && !generated_store_surface_production_source.contains("#[derive(")
        && generated_store_codec_source.contains(
            "pub(super) fn seal_nonce(counter: u64) -> [u8; SEALED_NONCE_BYTES] {\n    let mut nonce = [0u8; SEALED_NONCE_BYTES];\n    for (target, byte) in nonce.iter_mut().skip(4).zip(counter.to_be_bytes().iter()) {\n        *target = *byte;\n    }\n    nonce\n}",
        )
}

/// The text of a function from its signature line to its closing brace, which
/// stands alone at `indent`. `None` when the signature is not in the source.
fn rust_fn_text<'a>(source: &'a str, signature: &str, indent: &str) -> Option<&'a str> {
    let start = source.find(signature)?;
    let rest = &source[start..];
    let close = format!("\n{indent}}}\n");
    let end = rest.find(&close)?;
    Some(&rest[..end + close.len()])
}

/// Tokens of a branch, an early return or a short-circuit. A function whose
/// operands are a confidential kernel's has none of them.
const OPERAND_BRANCH_TOKENS: [&str; 14] = [
    "if ", "match ", "return", "&&", "||", "break", "continue", "while ", "loop ", "?", ".then",
    ".all(", ".any(", ".find(",
];

/// The 256-bit operations a confidential kernel runs on its operands, by
/// signature. Each is checked to have no token of a branch.
const KERNEL_UINT_OPERATIONS: [&str; 16] = [
    "    pub fn is_zero(self) -> bool {",
    "    fn nonzero_mask(self) -> u64 {",
    "    pub fn ct_eq(self, rhs: Self) -> bool {",
    "    fn select(mask: u64, when_set: Self, otherwise: Self) -> Self {",
    "    pub fn as_bool(self) -> bool {",
    "    pub fn to_usize_saturating(self) -> usize {",
    "    pub fn wrapping_add(self, rhs: Self) -> Self {",
    "    fn borrowing_sub(self, rhs: Self) -> (Self, u64) {",
    "    pub fn wrapping_sub(self, rhs: Self) -> Self {",
    "    pub fn ct_lt(self, rhs: Self) -> bool {",
    "    pub fn wrapping_neg(self) -> Self {",
    "    pub fn wrapping_mul(self, rhs: Self) -> Self {",
    "    pub fn div_rem(self, divisor: Self) -> (Self, Self) {",
    "    pub fn div_or_zero(self, divisor: Self) -> Self {",
    "    pub fn rem_or_zero(self, divisor: Self) -> Self {",
    "    fn shl1(self) -> Self {",
];

/// Whether the confidential kernel's binary operators, and the 256-bit
/// operations under them, are written without a branch or an early return
/// on an operand. Subtraction is a borrow chain, less-than is the borrow of
/// a subtraction, equality and the zero test fold the limbs, division runs
/// its 256 rounds with a masked subtraction and masks a zero divisor, and
/// the boolean operators do not short-circuit. This is a check of source
/// text: it says what the code asks for, not what a compiler emits
/// (`results/kernel_operator_instructions.json` counts the instructions of
/// one build).
fn check_kernel_operators_do_not_branch_on_operands(
    types_production_source: &str,
    generated_confidential_kernel_production_source: &str,
    generated_value_ops_production_source: &str,
) -> bool {
    let types = types_production_source;
    let kernel = generated_confidential_kernel_production_source;
    let value_ops = generated_value_ops_production_source;
    let branch_free = |text: &str| {
        !OPERAND_BRANCH_TOKENS
            .iter()
            .any(|token| text.contains(token))
    };
    let operations_branch_free = KERNEL_UINT_OPERATIONS.iter().all(|signature| {
        types.matches(signature).count() == 1
            && rust_fn_text(types, signature, "    ").is_some_and(branch_free)
    });
    let Some(evaluator) = rust_fn_text(kernel, "fn eval_confidential_kernel_binary_generated(", "")
    else {
        return false;
    };
    let masked_equality = [
        "fn masked_eq_uint256(lhs: Uint256, rhs: Uint256) -> bool {",
        "fn masked_eq_bytes<const N: usize>(lhs: [u8; N], rhs: [u8; N]) -> bool {",
        "fn masked_eq_u8(lhs: u8, rhs: u8) -> bool {",
    ]
    .iter()
    .all(|signature| rust_fn_text(value_ops, signature, "").is_some_and(branch_free));
    operations_branch_free
        // The formulas the operations rest on.
        && types.contains(
            "    pub fn is_zero(self) -> bool {\n        (self.0[0] | self.0[1] | self.0[2] | self.0[3]) == 0\n    }",
        )
        && types.contains(
            "            let difference = (self.0[idx] as u128)\n                .wrapping_sub(rhs.0[idx] as u128)\n                .wrapping_sub(borrow);\n            *slot = difference as u64;\n            borrow = (difference >> 64) & 1;",
        )
        && types.contains(
            "    pub fn wrapping_sub(self, rhs: Self) -> Self {\n        self.borrowing_sub(rhs).0\n    }",
        )
        && types.contains(
            "    pub fn ct_lt(self, rhs: Self) -> bool {\n        self.borrowing_sub(rhs).1 != 0\n    }",
        )
        && types.contains(
            "        for bit in (0..256).rev() {\n            remainder = remainder.shl1();\n            remainder.0[0] |= (self.0[bit / 64] >> (bit % 64)) & 1;\n            let (reduced, borrow) = remainder.borrowing_sub(divisor);\n            let fits = borrow.wrapping_sub(1);\n            remainder = Self::select(fits, reduced, remainder);\n            quotient.0[bit / 64] |= (fits & 1) << (bit % 64);\n        }",
        )
        && types.contains("            Self::select(divisor.nonzero_mask(), quotient, Self::ZERO),")
        && types.contains(
            "        let (_, remainder) = self.div_rem(divisor);\n        Self::select(divisor.nonzero_mask(), remainder, Self::ZERO)",
        )
        && types.contains("            *slot = (when_set.0[idx] & mask) | (otherwise.0[idx] & !mask);")
        && types.contains("    pub fn as_bool(self) -> bool {\n        !self.is_zero()\n    }")
        // The kernel's evaluator uses them, and no operator with a branch.
        // It dispatches on the operator, which is public, and `?` passes
        // on an operand of the wrong shape, which the program's types rule
        // out: neither depends on an operand's value.
        && !OPERAND_BRANCH_TOKENS
            .iter()
            .filter(|token| !matches!(**token, "match " | "?"))
            .any(|token| evaluator.contains(token))
        && evaluator.matches("match ").count() == 1
        && evaluator.contains(") -> Result<Value> {\n    match op {")
        && [
            "lhs_uint_generated(&lhs)?.wrapping_sub(lhs_uint_generated(&rhs)?),",
            "lhs_uint_generated(&lhs)?.div_or_zero(lhs_uint_generated(&rhs)?),",
            "lhs_uint_generated(&lhs)?.rem_or_zero(lhs_uint_generated(&rhs)?),",
            "BinaryOp::Eq => Ok(Value::Bool(Value::confidential_eq(&lhs, &rhs))),",
            "BinaryOp::Neq => Ok(Value::Bool(!Value::confidential_eq(&lhs, &rhs))),",
            "BinaryOp::Lt => Ok(Value::Bool(\n            lhs_uint_generated(&lhs)?.ct_lt(lhs_uint_generated(&rhs)?),",
            "BinaryOp::Lte => Ok(Value::Bool(\n            !lhs_uint_generated(&rhs)?.ct_lt(lhs_uint_generated(&lhs)?),",
            "BinaryOp::Gt => Ok(Value::Bool(\n            lhs_uint_generated(&rhs)?.ct_lt(lhs_uint_generated(&lhs)?),",
            "BinaryOp::Gte => Ok(Value::Bool(\n            !lhs_uint_generated(&lhs)?.ct_lt(lhs_uint_generated(&rhs)?),",
            "BinaryOp::And => Ok(Value::Bool(\n            lhs_bool_generated(&lhs)? & lhs_bool_generated(&rhs)?,",
            "BinaryOp::Or => Ok(Value::Bool(\n            lhs_bool_generated(&lhs)? | lhs_bool_generated(&rhs)?,",
        ]
        .iter()
        .all(|arm| evaluator.contains(arm))
        && ![" == ", " != ", " < ", " <= ", " > ", " >= ", ".div_rem(", "is_zero()"]
            .iter()
            .any(|operator| evaluator.contains(operator))
        // An array index is converted without a branch, and nowhere through
        // the conversion that has one.
        && kernel.matches("to_usize_saturating()").count() == 3
        && !kernel.contains("checked_to_usize")
        // Equality of values folds their bytes.
        && masked_equality
        && value_ops.contains(
            "            (Value::Uint(lhs), Value::Uint(rhs)) => masked_eq_uint256(*lhs, *rhs),",
        )
        && value_ops.contains(
            "    for (lhs_byte, rhs_byte) in lhs.into_iter().zip(rhs) {\n        diff |= lhs_byte ^ rhs_byte;\n    }\n    diff == 0",
        )
}

/// The files whose production code may build a write event from a class it
/// names: the generated helpers that seal a record in place, each behind the
/// check of the write's bytes.
const SEALED_WRITE_LABEL_FILES: [&str; 3] = [
    "runtime/uo-evm/src/generated_object_helpers.rs",
    "runtime/uo-evm/src/generated_oram_codecs.rs",
    "runtime/uo-store/src/generated_store_helpers.rs",
];

/// The files whose production code names the class `Update`: those that
/// label an event, and the two of the storage boundary that do not. The
/// store computes the class of a write from its own records, and the cipher
/// compares what the store returns with it
/// (`check_sealed_records_cross_the_storage_boundary`).
const SEALED_WRITE_CLASS_FILES: [&str; 5] = [
    "runtime/uo-evm/src/generated_object_helpers.rs",
    "runtime/uo-evm/src/generated_oram_codecs.rs",
    "runtime/uo-store/src/generated_store_helpers.rs",
    "runtime/uo-store/src/generated_surface.rs",
    "runtime/uo-store/src/storage.rs",
];

/// Whether the event of a sealed write is recorded only after the write has
/// been classified from its bytes. One function seals a record in place for
/// the runtime's objects and ORAM maps, and one for the store. Each keeps
/// the record it replaces, seals, and fails the call unless every 32-byte
/// unit of the new record is an `Update` of the unit it replaces
/// (`uo_core::is_update_write`). The label `Update` is written once on each
/// path, behind that check: `update_label_files` and
/// `shape_constructor_files` are the runtime's production files that name
/// the class or build an event from a named class, and
/// `write_event_brace_files` those where the event's type name opens a
/// brace, as a literal of it would: one function signature.
#[allow(clippy::too_many_arguments)]
fn check_sealed_writes_are_classified_from_their_bytes(
    core_trace_source: &str,
    generated_object_helpers_production_source: &str,
    generated_oram_codecs_production_source: &str,
    oram_production_source: &str,
    generated_store_helpers_production_source: &str,
    update_label_files: &[String],
    shape_constructor_files: &[String],
    write_event_brace_files: &[String],
) -> bool {
    let helpers = generated_object_helpers_production_source;
    let codecs = generated_oram_codecs_production_source;
    let store = generated_store_helpers_production_source;
    core_trace_source.contains("pub const STORAGE_OBSERVER_UNIT_BYTES: usize = 32;")
        && core_trace_source.contains(
            "pub fn is_update_write(old: &[u8], new: &[u8]) -> bool {\n    old.len() == new.len()\n        && !new.is_empty()\n        && old\n            .chunks(STORAGE_OBSERVER_UNIT_BYTES)\n            .zip(new.chunks(STORAGE_OBSERVER_UNIT_BYTES))\n            .all(|(old_unit, new_unit)| classify_write(old_unit, new_unit) == WriteClass::Update)\n}",
        )
        // Objects and ORAM maps: one function seals in place, and it records
        // the write only after the check.
        && helpers.contains(
            "    let replaced: Box<[u8]> = (&*physical).into();\n    if !cipher.seal_and_wipe_into_slice(aad.as_bytes(), payload, rng, physical) {",
        )
        && helpers.contains(
            "    if !is_update_write(&replaced, physical) {\n        bail!(\n            \"internal error: the sealed write of {} is not an Update of the record it replaces\",\n            location\n        );\n    }\n    // The record crosses the storage boundary here: the store takes it in\n    // place of the record it keeps at this location, and classifies the\n    // write from its own bytes.\n    cipher.store_sealed_record(location, physical)?;\n    record_write(physical.len())\n}",
        )
        && helpers.matches("seal_and_wipe_into_slice(").count() == 1
        && helpers.matches("    record_write(").count() == 1
        // The exact objects' event and the ORAM write log are fed by that
        // function and by nothing else.
        && helpers.matches("reseal_payload_and_record_write(").count() == 2
        && helpers.matches("WriteClass::Update").count() == 1
        && helpers.matches("from_shape(").count() == 1
        && helpers.contains("|physical_len| writes.push_update(location, physical_len),")
        && helpers.matches(".push_update(").count() == 1
        && codecs.matches("WriteClass::Update").count() == 1
        && codecs.contains(
            "    *slot = Some(OramWrite {\n        location: location.into(),\n        len,\n        class: WriteClass::Update,\n    });",
        )
        && codecs.matches("OramWrite {").count() == 2
        && codecs.matches("push_oram_write_update(").count() == 1
        && codecs.matches(".push_update(").count() == 0
        // An ORAM write keeps the class it was logged with.
        && codecs.matches("from_shape(").count() == 1
        && codecs.contains(
            "        uo_core::trace::PhysicalWriteEvent::from_shape(\n            object,\n            self.location.clone(),\n            self.len,\n            self.class,\n        )",
        )
        && oram_production_source.matches("push_oram_write_update(").count() == 1
        && oram_production_source.contains(
            "    pub(crate) fn push_update(&mut self, location: impl Into<String>, len: usize) -> Result<()> {\n        push_oram_write_update(self, location, len)\n    }",
        )
        && oram_production_source.matches(".push_update(").count() == 0
        && oram_production_source.matches("OramWrite {").count() == 1
        && !oram_production_source.contains("WriteClass::")
        // The store: its one in-place seal is checked before its event.
        && store.contains(
            "    let replaced: Box<[u8]> = (&*slot).into();\n    reseal_uo_store_slot_in_place(&aad, value, cipher, rng, slot)?;\n    if !is_update_write(&replaced, slot) {\n        bail!(\n            \"internal error: the sealed write of {} is not an Update of the record it replaces\",\n            object\n        );\n    }\n    Ok(PhysicalWriteEvent::from_shape(",
        )
        && store.matches("seal_and_wipe_into_slice(").count() == 1
        && store.matches("reseal_uo_store_slot_in_place(").count() == 2
        && store.matches("from_shape(").count() == 1
        // The other mention is the store's own test that all its writes
        // are updates.
        && store.matches("WriteClass::Update").count() == 2
        && store.contains(".all(|event| event.class == WriteClass::Update)")
        // Nothing else in the runtime names the class or builds an event
        // from a class, and none builds an event field by field: the type
        // name opens a brace once, where a function returns the event.
        && update_label_files == SEALED_WRITE_CLASS_FILES
        && shape_constructor_files == SEALED_WRITE_LABEL_FILES
        && write_event_brace_files == ["runtime/uo-evm/src/generated_oram_codecs.rs"]
        && codecs.matches("PhysicalWriteEvent {").count() == 1
        && codecs.contains(
            "    pub(crate) fn with_object(&self, object: &str) -> uo_core::trace::PhysicalWriteEvent {",
        )
}

/// Every sealed record crosses to the contract's store where it is opened
/// and where it is sealed, and nowhere else (invariant 18).
///
/// The generated helpers open a record in one function, which first names
/// the record to the store, and seal one in place in one function, which
/// hands the store the new record before the write is recorded. The cipher
/// reaches the store: a read is the store's comparison with the record it
/// keeps, and a write is preceded by the reservation of the seal counts made
/// so far and must come back classified as an `Update`. The store refuses a
/// sealed record whose seal count is not below its reservation, classifies
/// a write from the record it kept, and a store in files journals a
/// reservation before it takes effect. The engine commits a call in the
/// store before it takes the call's state, and a staged call that is
/// dropped abandons what it handed over.
fn check_sealed_records_cross_the_storage_boundary(
    generated_object_helpers_production_source: &str,
    generated_store_surface_production_source: &str,
    storage_production_source: &str,
    engine_impl_source: &str,
    store_meta_production_source: &str,
) -> bool {
    let helpers = generated_object_helpers_production_source;
    let surface = generated_store_surface_production_source;
    let storage = storage_production_source;
    // One open, behind the store's comparison.
    helpers.contains(
        "    cipher.check_stored_record(&location, physical)?;\n    cipher\n        .with_opened_payload(aad.as_bytes(), payload_len, physical, open)",
    ) && helpers.matches(".with_opened_payload(").count() == 1
        && helpers.matches("check_stored_record(").count() == 1
        // One seal in place; the store takes the record before the event.
        && helpers.contains(
            "    cipher.store_sealed_record(location, physical)?;\n    record_write(physical.len())",
        )
        && helpers.matches("store_sealed_record(").count() == 1
        && helpers.matches("    record_write(").count() == 1
        // The cipher's side.
        && surface.contains(
            "        match &self.storage {\n            Some(storage) => storage.read(location, record),\n            None => Ok(()),\n        }",
        )
        && surface.contains(
            "        storage.reserve_seals(self.seal_count())?;\n        let class = storage.write(location, record)?;\n        if class != WriteClass::Update {\n            bail!(",
        )
        && surface.contains(
            "        storage.reserve_seals(self.seal_count())?;\n        storage.create(location, record)",
        )
        && surface.matches("storage.write(").count() == 1
        && surface.matches("storage.create(").count() == 1
        // The cipher names the class once, to compare; the store names it
        // where it computes the class of a write from two records.
        && surface.matches("WriteClass::Update").count() == 1
        && storage.contains(
            "        .find(|class| *class != WriteClass::Update)\n        .unwrap_or(WriteClass::Update)",
        )
        && storage.matches("WriteClass::Update").count() == 2
        // The store's side.
        && storage.contains("        if &*record.bytes != held {\n            bail!(")
        && storage.contains("        if count >= reserved {\n            bail!(")
        && storage.matches("self.ensure_nonce_reserved(object, location, record)?;").count() == 2
        && storage.contains("        let class = sealed_write_class(&stored.bytes, record);")
        && storage.contains(
            "        self.append(&payload)?;\n        self.image.reserve_seals(object, below)",
        )
        // The engine commits in the store first, and a dropped call abandons.
        && engine_impl_source.contains(
            "        crate::instrumentation::time_store_persistence(|| staged.store.make_durable(&meta))?;\n        self.state = staged.state;",
        )
        && engine_impl_source.matches("self.state = staged.state;").count() == 1
        && engine_impl_source.contains(
            "        let store = StagedStore::begin(&self.storage)?;\n        let mut staged_state = stage_contract_runtime(&self.state)?;",
        )
        && store_meta_production_source.contains(
            "impl Drop for StagedStore {\n    fn drop(&mut self) {\n        if self.pending {\n            self.storage.with(|adapter| adapter.abandon());\n        }\n    }\n}",
        )
}

/// The fields of a struct in a Rust source, each with whether it is `pub`
/// (visible outside its crate). `None` if the struct is not found.
fn rust_struct_fields(source: &str, struct_name: &str) -> Option<Vec<(String, bool)>> {
    let start = source.find(&format!("pub struct {struct_name} {{\n"))?;
    let body = &source[start..];
    let body = &body[..body.find("\n}\n")?];
    let mut fields = Vec::new();
    for line in body.lines().skip(1) {
        let line = line.trim();
        let Some((name, _type)) = line.split_once(':') else {
            continue;
        };
        let (name, public) = match name.strip_prefix("pub(crate) ") {
            Some(name) => (name, false),
            None => match name.strip_prefix("pub ") {
                Some(name) => (name, true),
                None => (name, false),
            },
        };
        if !name.is_empty()
            && name
                .chars()
                .all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
        {
            fields.push((name.to_owned(), public));
        }
    }
    Some(fields)
}

/// Whether a call's private evidence stays inside the runtime in a
/// production build. The receipt has the observer's fields and no other, and
/// every field of the evidence is private to `uo-core`. The evidence and the
/// trace that holds it can be written out only by a test or diagnostics
/// build, nothing hands the evidence out, and it is wiped on drop. A call's
/// result carries the receipt in every build and the trace only in a test or
/// diagnostics build, no engine function returns a trace, and the CLI prints
/// the trace or a proof object only in a diagnostics build.
fn check_private_evidence_stays_inside_the_runtime(
    core_trace_source: &str,
    engine_impl_source: &str,
    main_source: &str,
    core_manifest: &str,
    runtime_manifest: &str,
) -> bool {
    let fields = |name: &str| rust_struct_fields(core_trace_source, name).unwrap_or_default();
    let named = |names: &[&str], public: bool| -> Vec<(String, bool)> {
        names
            .iter()
            .map(|name| ((*name).to_owned(), public))
            .collect()
    };
    let runtime_dependencies = runtime_manifest
        .split_once("[dependencies]")
        .and_then(|(_, rest)| rest.split_once("[dev-dependencies]"))
        .map(|(dependencies, _)| dependencies)
        .unwrap_or_default();
    fields("PublicReceipt") == named(uo_core::PUBLIC_RECEIPT_FIELDS, true)
        && fields("PrivateEvidence") == named(uo_core::PRIVATE_EVIDENCE_FIELDS, false)
        && fields("ExecutionTrace")
            == [("receipt".to_owned(), true), ("evidence".to_owned(), false)]
        && uo_core::PUBLIC_RECEIPT_FIELDS
            .iter()
            .all(|field| !uo_core::PRIVATE_EVIDENCE_FIELDS.contains(field))
        && core_trace_source.contains(
            "#[derive(PartialEq, Default)]\n#[cfg_attr(\n    any(test, feature = \"diagnostics\"),\n    derive(Debug, Serialize, Deserialize)\n)]\npub struct PrivateEvidence {",
        )
        && core_trace_source.contains(
            "#[derive(Debug, PartialEq, Default)]\n#[cfg_attr(any(test, feature = \"diagnostics\"), derive(Serialize, Deserialize))]\npub struct ExecutionTrace {",
        )
        && core_trace_source.contains(
            "impl Drop for PrivateEvidence {\n    fn drop(&mut self) {\n        self.wipe();\n    }\n}",
        )
        && core_trace_source.contains(
            "    pub fn into_receipt(self) -> PublicReceipt {\n        self.receipt\n    }",
        )
        && !core_trace_source.contains("pub fn evidence(")
        && !core_trace_source.contains("-> PrivateEvidence")
        && !core_trace_source.contains("&PrivateEvidence")
        && engine_impl_source.contains(
            "pub struct CallResult {\n    pub return_value: Option<Value>,\n    pub encrypted_return: Option<EncryptedReturnPayload>,\n    pub aborted: bool,\n    /// What the observer of the call sees.\n    #[cfg(not(any(test, feature = \"diagnostics\")))]\n    pub receipt: PublicReceipt,\n    /// The call's receipt and its private evidence.\n    #[cfg(any(test, feature = \"diagnostics\"))]\n    pub trace: ExecutionTrace,\n}",
        )
        && engine_impl_source.contains(
            "            #[cfg(not(any(test, feature = \"diagnostics\")))]\n            receipt: trace.into_receipt(),\n            #[cfg(any(test, feature = \"diagnostics\"))]\n            trace,",
        )
        && !engine_impl_source.contains("-> Result<ExecutionTrace>")
        && !engine_impl_source.contains("-> ExecutionTrace")
        // The receipt is the CLI's one ungated format and one ungated arm.
        && main_source.contains("enum OutputFormat {\n    Receipt,\n    #[cfg(feature = \"diagnostics\")]\n    Trace,")
        && main_source.contains(
            "        OutputFormat::Receipt => {\n            println!(\"{}\", serde_json::to_string_pretty(result.receipt())?);\n        }",
        )
        && main_source.matches("\n        OutputFormat::").count()
            == main_source
                .matches("\n        #[cfg(feature = \"diagnostics\")]\n        OutputFormat::")
                .count()
                + 1
        && main_source.matches("\n    #[cfg(feature = \"diagnostics\")]\n    ").count()
            == main_source.matches("\n        #[cfg(feature = \"diagnostics\")]\n        OutputFormat::").count() + 3
        // Only the diagnostics feature, or a test build, turns on the
        // evidence's serialization.
        && core_manifest.contains("\ndiagnostics = []\n")
        && !core_manifest.contains("default =")
        && runtime_manifest.contains("\ndiagnostics = [\"uo-core/diagnostics\"]\n")
        && !runtime_manifest.contains("default =")
        && runtime_dependencies.contains("\nuo-core = { path = \"../../crates/uo-core\" }\n")
        && !runtime_dependencies.contains("diagnostics")
}

/// Whether a production call is accepted on evidence a caller can know and
/// answered with a receipt of the deployment's chain. The evidence names the
/// receipt the runtime issued last, in place of the hash of a proof bundle,
/// and the preflight compares the two. The module that builds receipts never
/// sees a call's trace or its private evidence: a receipt is built from the
/// evidence, the receipt before it, the call's public receipt, the counters
/// and two state digests, and it is checked against the predicates a holder
/// of the chain applies. The engine builds it from the staged call, commits
/// only after that, and only then moves the head of the chain.
fn check_production_calls_issue_chained_receipts(
    deployment_source: &str,
    engine_impl_source: &str,
) -> bool {
    let receipt_fields: Vec<(String, bool)> = [
        "request_sha256",
        "previous_receipt_sha256",
        "public_state_before_sha256",
        "public_state_after_sha256",
        "ciphertext_store_before_sha256",
        "ciphertext_store_after_sha256",
        "public_receipt_sha256",
        "freshness_epoch",
        "rollback_counter",
        "next_call_counter",
    ]
    .iter()
    .map(|field| ((*field).to_owned(), true))
    .collect();
    !deployment_source.contains("proof_bundle")
        && !engine_impl_source.contains("proof_bundle")
        && !deployment_source.contains("ExecutionTrace")
        && !deployment_source.contains("PrivateEvidence")
        && deployment_source.contains(
            "    pub previous_receipt_sha256: String,\n    pub translation_validation_certificate_sha256: String,\n}",
        )
        && deployment_source.contains(
            "    require_equal(\n        \"previous_receipt_sha256\",\n        &evidence.previous_receipt_sha256,\n        last_receipt_sha256,\n    )",
        )
        && rust_struct_fields(deployment_source, "ProductionReceipt") == Some(receipt_fields)
        && deployment_source.contains(
            "    pub(crate) fn for_call(\n        evidence: &ProductionCallEvidence,\n        previous: &ProductionReceipt,\n        public_receipt: &PublicReceipt,\n        counters_after: RuntimeFreshnessSnapshot,\n        public_state_after_sha256: String,\n        ciphertext_store_after_sha256: String,\n    ) -> Result<Self> {",
        )
        && deployment_source.contains(
            "        receipt.follows(previous)?;\n        receipt.binds_call(evidence, public_receipt)?;\n        Ok(receipt)",
        )
        && deployment_source.contains(
            "        receipt.binds_deployment(artifact, policy)?;\n        Ok(receipt)",
        )
        && engine_impl_source.contains(
            "            self.inner.freshness.snapshot(),\n            &self.last_receipt_sha256,\n        )?;",
        )
        && engine_impl_source.contains(
            "        let receipt = ProductionReceipt::for_call(\n            evidence,\n            &self.last_receipt,\n            &staged.trace.receipt,\n            staged.freshness.snapshot(),\n            staged.state.public_state_digest()?,\n            staged.state.ciphertext_store_digest()?,\n        )?;\n        let receipt_sha256 = receipt.sha256()?;\n        let call = self.inner.commit_staged(staged)?.0;\n        self.last_receipt = receipt.clone();\n        self.last_receipt_sha256 = receipt_sha256;\n        Ok(ProductionCallResult { call, receipt })",
        )
        && engine_impl_source.matches("self.last_receipt = ").count() == 1
        && engine_impl_source.matches("self.last_receipt_sha256 = ").count() == 1
        && engine_impl_source.matches("commit_staged(staged)").count() == 2
}

/// Whether the production path's freshness errors carry no runtime value. An
/// error reaches the caller, and a caller whose evidence is wrong has not
/// shown that it knows the runtime's epoch and counters. `deployment.rs` reads
/// each field of the freshness snapshot once, as an operand of
/// `require_equal_counter`, and that helper reports the field's name and
/// nothing else.
fn check_production_errors_carry_no_runtime_freshness_value(deployment_source: &str) -> bool {
    [
        "freshness.epoch",
        "freshness.rollback_counter",
        "freshness.next_call_counter",
    ]
    .iter()
    .all(|field| deployment_source.matches(field).count() == 1)
        && deployment_source.contains(
            "fn require_equal_counter(label: &str, evidence: u64, runtime: u64) -> Result<()> {\n    if evidence != runtime {\n        bail!(\"production runtime {label} mismatch\");\n    }\n    Ok(())\n}",
        )
}

/// Whether a contract instance's `Debug` form shows none of its state. The
/// instance holds the runtime's secrets, and a caller can format it.
fn check_contract_instance_debug_is_opaque(engine_impl_source: &str) -> bool {
    !engine_impl_source.contains("#[derive(Debug)]\npub struct ContractInstance {")
        && engine_impl_source.contains("impl std::fmt::Debug for ContractInstance {")
        && engine_impl_source
            .contains("f.debug_struct(\"ContractInstance\").finish_non_exhaustive()")
}

/// The attribute of an item that only a build which can export a call's
/// evidence has: a test build or a diagnostics build.
const EVIDENCE_BUILD_GATE: &str = "#[cfg(any(test, feature = \"diagnostics\"))]";

/// Whether `source` defines each function of `names` once, on the line under
/// the attribute that leaves it out of a production build.
fn defined_only_in_evidence_builds(source: &str, names: &[&str]) -> bool {
    let lines: Vec<&str> = source.lines().collect();
    names.iter().all(|name| {
        let definition = format!("fn {name}(");
        let mut definitions = lines
            .iter()
            .enumerate()
            .filter(|(_, line)| line.contains(&definition));
        match (definitions.next(), definitions.next()) {
            (Some((index, _)), None) => index > 0 && lines[index - 1].trim() == EVIDENCE_BUILD_GATE,
            _ => false,
        }
    })
}

/// Whether a production call records no witness of its hidden ORAM state.
/// The functions that decode a position map or read an access counter for a
/// witness, and those that keep, move and audit the witness, exist only in a
/// build that can export a call's evidence, so a production build cannot
/// call one: it would not compile. The runtime's kept witness is a field of
/// such a build alone. In a production build a call starts and ends with no
/// snapshot, and `uo-core` then builds no proof bundle, which would carry
/// the position maps, and runs the checks of the evidence that need none.
fn check_production_calls_record_no_position_map_witness(
    state_source: &str,
    theorem_source: &str,
    oram_source: &str,
    objects_source: &str,
    core_trace_source: &str,
) -> bool {
    defined_only_in_evidence_builds(
        state_source,
        &[
            "witness_before_call",
            "witness_after_call",
            "keep_decoded_witness",
            "audit_kept_witness",
            "records_witness",
            "path_oram_access_counter_witnesses",
            "witness_snapshot",
        ],
    ) && defined_only_in_evidence_builds(
        oram_source,
        &["path_position_map_witness", "access_counter_witness"],
    ) && defined_only_in_evidence_builds(
        objects_source,
        &[
            "path_oram_position_map_witness",
            "exposes_path_oram_witnesses",
            "path_oram_access_counter_witness",
        ],
    )
        // The decoders of a position map have one caller each.
        && oram_source.matches("tree_position_map_witness_leaves(").count() == 1
        && oram_source.matches("path_position_map_witness_leaves(").count() == 1
        && !state_source.contains("position_map_witness_leaves(")
        && !objects_source.contains("position_map_witness_leaves(")
        && state_source.contains(
            "    #[cfg(any(test, feature = \"diagnostics\"))]\n    kept_witness: Option<Arc<CommittedRuntimeWitnessSnapshot>>,\n",
        )
        && state_source.matches("kept_witness: Option<").count() == 1
        // A production call starts and ends with no snapshot.
        && state_source.contains(
            "        #[cfg(any(test, feature = \"diagnostics\"))]\n        let call_start = if self.records_witness() {\n            TracedRuntimeCallStart::new(self.witness_before_call()?)\n        } else {\n            TracedRuntimeCallStart::unwitnessed()\n        };\n        #[cfg(not(any(test, feature = \"diagnostics\")))]\n        let call_start = TracedRuntimeCallStart::unwitnessed();\n        Ok((call_start, public_call, recorder))",
        )
        && state_source.matches("TracedRuntimeCallStart::new(").count() == 1
        && state_source.contains(
            "    #[cfg(not(any(test, feature = \"diagnostics\")))]\n    pub(in crate::runtime) fn finish_traced_call(\n        &mut self,\n        call_outcome: RuntimeCallOutcome,\n    ) -> Result<TracedRuntimeCallOutcome> {\n        Ok(TracedRuntimeCallOutcome::unwitnessed(call_outcome))\n    }",
        )
        && state_source.contains(
            "    #[cfg(any(test, feature = \"diagnostics\"))]\n    pub(in crate::runtime) fn finish_traced_call(\n        &mut self,\n        call_outcome: RuntimeCallOutcome,\n        artifact: &CompiledArtifact,\n        recorder: &CallRecorder,\n    ) -> Result<TracedRuntimeCallOutcome> {\n        if !self.records_witness() {\n            return Ok(TracedRuntimeCallOutcome::unwitnessed(call_outcome));\n        }\n        Ok(TracedRuntimeCallOutcome::new(\n            call_outcome,\n            self.witness_after_call(artifact, recorder)?,\n        ))\n    }",
        )
        && state_source.matches("TracedRuntimeCallOutcome::new(").count() == 1
        && theorem_source.contains(
            "    #[cfg(any(test, feature = \"diagnostics\"))]\n    let traced_outcome = runtime.finish_traced_call(call_outcome, artifact, &context.recorder)?;\n    #[cfg(not(any(test, feature = \"diagnostics\")))]\n    let traced_outcome = runtime.finish_traced_call(call_outcome)?;",
        )
        && theorem_source.matches(".finish_traced_call(").count() == 2
        // Without a snapshot of both ends a call has no hidden ORAM state,
        // and its trace is finalized by the checks that need none.
        && core_trace_source.contains(
            "    pub fn unwitnessed() -> Self {\n        Self {\n            runtime_state_before: None,\n        }\n    }",
        )
        && core_trace_source.contains(
            "    pub fn unwitnessed(call_outcome: RuntimeCallOutcome) -> Self {\n        Self {\n            call_outcome,\n            runtime_state_after: None,\n        }\n    }",
        )
        && core_trace_source.contains(
            "            match (call_start.runtime_state_before, self.runtime_state_after) {\n                (Some(runtime_state_before), Some(runtime_state_after)) => {",
        )
        && core_trace_source.contains(
            "                _ => None,\n            };\n        FinalizedRuntimeCallTraceParts::new(self.call_outcome, runtime_witness_state)",
        )
        && core_trace_source.contains(
            "        let runtime_oram_position_maps_unrecorded = runtime_witness_state.is_none();",
        )
        && core_trace_source.matches("runtime_oram_position_maps_unrecorded = ").count() == 1
        && core_trace_source.contains(
            "            trace.check_evidence_without_position_maps(artifact, confidential)?;\n        } else {\n            if confidential {\n                trace.runtime_confidential_proof_bundle_family(artifact)?;\n            }\n            trace.materialize_runtime_trusted_kernel_bundle()?;\n        }\n        Ok(trace)",
        )
        && core_trace_source.contains(
            "        if !self.evidence.runtime_oram_access_counters_before.is_empty()\n            || !self.evidence.runtime_oram_access_counters_after.is_empty()\n            || !self.evidence.runtime_oram_position_map_before.is_empty()\n            || !self.evidence.runtime_oram_position_map_after.is_empty()\n            || self.evidence.runtime_oram_leaf_schedule.len()\n                != self.evidence.runtime_oram_leaf_state_transitions.len()\n        {\n            return Err(RefinementWitnessError::OramLeafStateMismatch.into());\n        }\n        let kernel_witness = self.checked_runtime_kernel_witness()?;\n        let controller_observer = self.reconstructed_runtime_controller_observer_certificate()?;",
        )
        && core_trace_source.contains(
            "        validate_path_oram_leaf_schedule(\n            &self.evidence.runtime_oram_leaf_schedule,\n            &refinement_trace.logical_accesses,\n            &refinement_trace.physical_reads,\n            &refinement_trace.physical_writes,\n            &self.evidence.runtime_oram_objects,\n        )?;\n        validate_refinement_outcome(\n            &refinement_trace,\n            &controller_observer.public_outcome,\n            kernel_witness.as_ref(),\n            None,\n            &controller_observer.controller_certificate,\n            &self.evidence.runtime_oram_objects,\n        )?;\n        if confidential {\n            self.check_runtime_confidential_kernel_bundles(artifact)?;\n        }\n        Ok(())",
        )
}

/// Whether every call of a build that exports evidence audits the witness
/// the runtime keeps. The witness before a call is a copy of the kept one
/// and the witness after it is that copy moved by the call's own leaf
/// transitions, so the check that the transitions carry one to the other
/// says nothing about the store. The audit does: before and after the call
/// it decodes the witness from the whole store, as every call did before
/// the witness was kept, and fails the call unless the kept one equals it.
/// The audit is on for every thread until it is turned off, and the probe
/// turns it off in one place, for the calls it times.
fn check_evidence_builds_audit_the_kept_position_map_witness(
    state_source: &str,
    instrumentation_source: &str,
    probe_source: &str,
    capacity_sweep_source: &str,
) -> bool {
    // Written in two parts, so that this function's own text does not count.
    let switch_call = concat!("set_position_map_witness", "_audit(");
    let guard = concat!("WitnessAudit", "Off::new()");
    state_source.contains(
        "            let kept = match &self.kept_witness {\n                Some(kept) => {\n                    if crate::instrumentation::witness_audit_enabled() {\n                        self.audit_kept_witness(\"before a call\")?;\n                    }\n                    Arc::clone(kept)\n                }\n                None => {\n                    let decoded = Arc::new(self.committed.witness_snapshot()?);\n                    self.kept_witness = Some(Arc::clone(&decoded));\n                    decoded\n                }\n            };\n            Ok(kept.duplicate())",
    ) && state_source.contains(
        "            let after = next.duplicate();\n            self.kept_witness = Some(Arc::new(next));\n            if crate::instrumentation::witness_audit_enabled() {\n                self.audit_kept_witness(\"after a call\")?;\n            }\n            Ok(after)",
    ) && state_source.contains(
        "        let decoded = self.committed.witness_snapshot()?;\n        crate::instrumentation::count_witness_audit();\n        if decoded != **kept {\n            bail!(\"the kept position-map witness differs from the decoded store {context}\");\n        }\n        Ok(true)",
    ) && state_source.matches("witness_audit_enabled()").count() == 2
        // On until turned off, for each thread.
        && instrumentation_source.contains(
            "    static WITNESS_AUDIT_OFF: Cell<bool> = const { Cell::new(false) };",
        )
        && instrumentation_source.contains(concat!(
            "pub fn set_position_map_witness",
            "_audit(on: bool) -> bool {\n    WITNESS_AUDIT_OFF.with(|off| !off.replace(!on))\n}",
        ))
        && instrumentation_source.contains(
            "pub(crate) fn witness_audit_enabled() -> bool {\n    #[cfg(feature = \"diagnostics\")]\n    {\n        cfg!(test) || !WITNESS_AUDIT_OFF.with(Cell::get)\n    }\n    #[cfg(not(feature = \"diagnostics\"))]\n    {\n        true\n    }\n}",
        )
        && instrumentation_source.matches("WITNESS_AUDIT_OFF").count() == 3
        // The probe turns the audit off through one guard, which turns it
        // back on, and only where it times calls: in the capacity sweep,
        // which audits after each level, and in the latency report.
        && capacity_sweep_source.contains(concat!(
            "impl WitnessAuditOff {\n    pub(crate) fn new() -> Self {\n        Self(uo_evm::set_position_map_witness",
            "_audit(false))\n    }\n}\n\nimpl Drop for WitnessAuditOff {\n    fn drop(&mut self) {\n        uo_evm::set_position_map_witness",
            "_audit(self.0);\n    }\n}",
        ))
        && capacity_sweep_source.matches(switch_call).count() == 2
        && capacity_sweep_source.matches(guard).count() == 1
        && capacity_sweep_source.contains(
            "            let audited = instance\n                .audit_kept_position_map_witness()\n                .context(\"auditing the kept position-map witness\")?;",
        )
        && capacity_sweep_source.contains(
            "            \"kept_witness_matches_store_after_every_level\": measured_levels > 0\n                && audited_levels == measured_levels,",
        )
        && probe_source.matches(switch_call).count() == 0
        && probe_source.matches(guard).count() == 1
        && probe_source.contains(concat!(
            "fn run_latency_memory(suite: &BTreeMap<&'static str, BenchArtifacts>) -> Result<JsonValue> {\n    // Calls are timed with the audit of the kept witness off.\n    let _witness_audit_off = capacity_sweep::WitnessAudit",
            "Off::new();",
        ))
}

/// Whether a call is staged, loaded and committed without copying the
/// store. A committed object is held by reference: the state a call is
/// staged on is a table of the committed objects, and a commit puts new
/// objects in the place of those the call loaded and keeps the others. No
/// sealed object has a cold clone. A Path ORAM map's sealed records are held
/// by reference too: the copy of the map that a call loads shares them, a
/// write copies the record it replaces, and a record is zeroed only by its
/// last holder. An object keeps the digest of its sealed records and
/// forgets it when it is handed out to be changed, so a digest of the
/// ciphertext reads the objects written since the last one.
fn check_a_call_copies_no_committed_object(
    state_source: &str,
    objects_source: &str,
    oram_source: &str,
    generated_oram_codecs_source: &str,
) -> bool {
    state_source.contains(
        "struct RuntimeObjectEntry {\n    object_id: u32,\n    object: Arc<TableObject>,\n}",
    ) && state_source.contains(
        "struct TableObject {\n    object: RuntimeObject,\n    sealed_records: OnceLock<SealedRecordsDigest>,\n}",
    ) && state_source.contains(
        "    fn share(&self) -> Self {\n        Self {\n            object_id: self.object_id,\n            object: Arc::clone(&self.object),\n        }\n    }",
    ) && state_source.contains(
        "    fn share(&self) -> Result<Self> {\n        let mut entries = FixedBoxBuilder::new(self.entries.len());\n        for entry in self.entries.iter() {\n            entries.push(entry.share())?;\n        }\n        Ok(Self::new(entries.finish()?))\n    }",
    ) && state_source.contains(
        "    fn share(&self) -> Result<Self> {\n        Ok(Self {\n            objects: self.objects.share()?,\n        })\n    }",
    ) && state_source.contains("            committed: self.committed.share()?,\n")
        // A commit keeps the committed object of every object the call did
        // not load, and takes the call's own for the others.
        && state_source.contains(
            "                Some(Ordering::Greater) | None => {\n                    // The call did not load this object: the next state\n                    // holds the committed one itself.\n                    next_objects.push(old.share())?;\n                }",
        )
        && state_source.contains(
            "                    let object = entry.into_owned().ok_or_else(|| {\n                        anyhow!(\"object {id} of the call was shared with another state at commit\")\n                    })?;",
        )
        && state_source.contains(
            "        if Arc::strong_count(&self.object) > 1 {\n            if !self.object.object.committed_cache_is_cold() {\n                bail!(\"object {object_id} was shared with committed state and not cold\");\n            }\n            return Ok(self);\n        }",
        )
        // Nothing clones a committed sealed object.
        && !state_source.contains("clone_cold")
        && !state_source.contains("clone_committed_cold")
        && !objects_source.contains("clone_committed_cold")
        && !oram_source.contains("clone_committed_cold")
        // An object's digest is that of its records.
        && state_source.contains(
            "        if let Some(digest) = self.sealed_records.get() {\n            return Ok(*digest);\n        }\n        let digest = SealedRecordsDigest::of(object_id, &self.object)?;",
        )
        && state_source.contains(
            "        let held = Arc::get_mut(&mut self.object)?;\n        held.sealed_records = OnceLock::new();\n        Some(&mut held.object)",
        )
        && state_source.matches("Arc::get_mut(").count() == 1
        && state_source.contains(
            "        for entry in self.entries.iter() {\n            entry\n                .object\n                .sealed_records_digest(entry.object_id)?\n                .add_to(entry.object_id, &mut store);\n        }",
        )
        // The sealed records of a Path ORAM map.
        && oram_source.contains(
            "pub(crate) struct OramStorage {\n    directory_pages: Box<[SealedPage]>,\n    buckets: Box<[SealedPage]>,\n    access_counter_slot: Box<[u8]>,\n}",
        )
        && oram_source.contains("#[derive(Clone, Debug)]\npub(crate) struct SealedPage(Arc<[u8]>);")
        && oram_source.contains(
            "    fn deref_mut(&mut self) -> &mut [u8] {\n        Arc::make_mut(&mut self.0)\n    }",
        )
        && oram_source.contains(
            "    pub(crate) fn wipe(&mut self) {\n        if let Some(bytes) = Arc::get_mut(&mut self.0) {\n            bytes.fill(0);\n        }\n    }",
        )
        && generated_oram_codecs_source.contains(
            "fn clone_oram_storage(storage: &super::OramStorage) -> super::OramStorage {\n    super::OramStorage {\n        directory_pages: storage.directory_pages.clone(),\n        buckets: storage.buckets.clone(),\n        access_counter_slot: storage.access_counter_slot.clone(),\n    }\n}",
        )
        && generated_oram_codecs_source.contains(
            "        for page in &mut self.storage.directory_pages {\n            page.wipe();\n        }\n        for bucket in &mut self.storage.buckets {\n            bucket.wipe();\n        }",
        )
        && !generated_oram_codecs_source.contains("[Box<[u8]>],")
}

/// The names of the types of a run item, and of the variants that hold
/// one. No production file of the runtime writes them: it builds a run
/// through `uo-core` (`PhysicalReadItem::scan`, `LogicalAccessItem::scan`,
/// `PhysicalWriteItem::rewrite`).
const TRACE_RUN_TYPE_PATTERNS: [&str; 5] = [
    "PhysicalRewrite",
    "PhysicalScan",
    "LogicalScan {",
    "Item::Rewrite(",
    "Item::Scan(",
];

/// The one file of the runtime whose production code builds an item of a
/// trace: the call recorder.
const TRACE_RUN_RECORDER_FILES: [&str; 1] = ["runtime/uo-evm/src/controller.rs"];

/// Whether a run in a trace stands for the events the runtime recorded. A
/// trace is its events in order, and an item of it may stand for a run of
/// them: the scan or the rewrite of an exact object, or the logical scan of
/// a map. `uo-core` names the events of a run, hashes a trace over its
/// events, and rejects a run that could hold an event of a Path ORAM
/// access, so nothing depends on how the events are grouped. The recorder
/// keeps a run through `uo-core` alone. It keeps a scan from the slot count
/// and the one length the slots of its object have. It keeps a rewrite from
/// the writes it was handed one at a time, each the `Update` of the next
/// slot (`ExactObjectSlots::takes_write`), so the class a rewrite stands
/// for is that of writes classified from their bytes. `run_type_files` are
/// the runtime's production files that name the type of a run item, and
/// `rewrite_files` and `scan_files` those that build a rewrite or a scan.
fn check_trace_runs_stand_for_recorded_events(
    core_trace_source: &str,
    controller_production_source: &str,
    objects_production_source: &str,
    run_type_files: &[String],
    rewrite_files: &[String],
    scan_files: &[String],
) -> bool {
    let trace = core_trace_source;
    let recorder = controller_production_source;
    let objects = objects_production_source;
    // The events of a run, as `uo-core` names them.
    trace.contains(
        "        match self.kind {\n            ExactObjectKind::Cell => self.object.clone(),\n            ExactObjectKind::Array => format!(\"{}[{slot}]\", self.object),\n            ExactObjectKind::Map => format!(\"{}#{slot}\", self.object),\n        }",
    ) && trace.contains(
        "            Self::Scan(item) => (index < item.scan.slots).then(|| PhysicalReadEvent {\n                object: item.scan.object.clone(),\n                location: item.scan.location(index),\n                len: item.scan.len,\n            }),",
    ) && trace.contains(
        "            Self::Rewrite(item) => (index < item.rewrite.slots).then(|| PhysicalWriteEvent {\n                object: item.rewrite.object.clone(),\n                location: item.rewrite.location(index),\n                len: item.rewrite.len,\n                class: WriteClass::Update,\n            }),",
    ) && trace.contains(
        "            Self::Scan(item) => (index < item.scan.slots).then(|| LogicalEvent {\n                kind: item.scan.kind.clone(),\n                object: item.scan.object.clone(),\n                detail: format!(\"slot:{index}\"),\n            }),",
    ) && trace.contains(
        "    pub fn events(&self) -> impl Iterator<Item = I::Event> + '_ {\n        self.0\n            .iter()\n            .flat_map(|item| (0..item.event_count()).filter_map(move |index| item.event(index)))\n    }",
    )
        // The hashes and the transcript of a trace are of its events.
        && trace.contains(
            "        let normalized_physical = self\n            .physical_writes\n            .events()\n            .map(|event| (event.object, event.location, event.class, event.len))\n            .collect::<Vec<_>>();\n        let normalized_reads = self\n            .physical_reads\n            .events()\n            .map(|event| (event.object, event.location, event.len))\n            .collect::<Vec<_>>();\n        let logical_accesses = self.logical_accesses.events().collect::<Vec<_>>();",
        )
        && trace.contains("            logical_access_trace_hash: hash_json(&logical_accesses)?,")
        && trace.contains("            physical_read_trace_hash: hash_json(&normalized_reads)?,")
        && trace.contains("            physical_write_trace_hash: hash_json(&normalized_physical)?,")
        && trace.contains("        for (index, event) in self.logical_accesses.events().enumerate() {")
        && trace.contains("        for (index, event) in self.physical_reads.events().enumerate() {")
        && trace.contains("        for (index, event) in self.physical_writes.events().enumerate() {")
        // A run holds no event of a Path ORAM access.
        && trace.contains(
            "            Err(run) => {\n                if path_objects.contains(run.object.as_str()) || !run.is_well_formed() {\n                    return Err(RefinementWitnessError::OramLeafScheduleMismatch);\n                }\n            }",
        )
        && trace.contains(
            "            LogicalAccessItem::Scan(run) => {\n                if is_oram_logical_kind(&run.scan.kind) {\n                    return Err(RefinementWitnessError::MalformedOramLogicalTrace {",
        )
        // A rewrite takes the `Update` of its next slot and no other write,
        // and a recorder's item is the run, or its one event.
        && trace.contains(
            "    pub fn none_of(object: impl Into<String>, kind: ExactObjectKind) -> Self {\n        Self {\n            object: object.into(),\n            kind,\n            slots: 0,\n            len: 0,\n        }\n    }",
        )
        && trace.contains(
            "    pub fn takes_write(&mut self, event: &PhysicalWriteEvent) -> bool {\n        let next = event.class == WriteClass::Update\n            && event.object == self.object\n            && self.is_location(self.slots, &event.location)\n            && (self.slots == 0 || event.len == self.len);\n        if next {\n            self.len = event.len;\n            self.slots += 1;\n        }\n        next\n    }",
        )
        && trace.contains(
            "    fn of_run(run: Self) -> Option<Self> {\n        match run.event_count() {\n            0 => None,\n            1 => run.event(0).map(Self::from_event),\n            _ => Some(run),\n        }\n    }",
        )
        && trace.contains(
            "    pub fn scan(scan: ExactObjectSlots) -> Option<Self> {\n        Self::of_run(Self::Scan(PhysicalScan { scan }))\n    }",
        )
        && trace.contains(
            "    pub fn rewrite(rewrite: ExactObjectSlots) -> Option<Self> {\n        Self::of_run(Self::Rewrite(PhysicalRewrite { rewrite }))\n    }",
        )
        && trace.contains(
            "    pub fn scan(scan: LogicalScanSlots) -> Option<Self> {\n        Self::of_run(Self::Scan(LogicalScan { scan }))\n    }",
        )
        // The recorder: a rewrite starts empty, grows by the writes it
        // takes, and becomes an item when it ends. Nothing else touches it.
        && recorder.contains("    open_rewrite: Option<ExactObjectSlots>,")
        && recorder.contains(
            "    pub(crate) fn physical_write(&mut self, event: PhysicalWriteEvent) {\n        self.metrics.physical_writes += 1;\n        if let Some(run) = self.open_rewrite.as_mut() {\n            if run.takes_write(&event) {\n                return;\n            }\n            self.end_exact_rewrite();\n        }\n        self.physical_writes.push(PhysicalWriteItem::Write(event));\n    }",
        )
        && recorder.contains(
            "    pub(crate) fn begin_exact_rewrite(&mut self, object: &str, kind: ExactObjectKind) {\n        self.end_exact_rewrite();\n        self.open_rewrite = Some(ExactObjectSlots::none_of(object, kind));\n    }",
        )
        && recorder.contains(
            "    pub(crate) fn end_exact_rewrite(&mut self) {\n        let rewrite = self.open_rewrite.take();\n        if let Some(item) = rewrite.and_then(PhysicalWriteItem::rewrite) {\n            self.physical_writes.push(item);\n        }\n    }",
        )
        && recorder.matches("open_rewrite").count() == 4
        && recorder.matches("takes_write(").count() == 1
        && recorder.matches("PhysicalWriteItem::rewrite").count() == 1
        // A raw write and the end of the call end an open rewrite first.
        && recorder.contains(
            "        self.end_exact_rewrite();\n        self.physical_writes.push(PhysicalWriteItem::Write(event));\n    }",
        )
        && recorder.matches("self.end_exact_rewrite();").count() == 4
        // Its scans count one read for each slot.
        && recorder.contains(
            "        let scan = ExactObjectSlots {\n            object: object.into(),\n            kind,\n            slots,\n            len,\n        };\n        if let Some(item) = PhysicalReadItem::scan(scan) {\n            self.metrics.physical_reads += slots;\n            self.physical_reads.push(item);\n        }",
        )
        && recorder.contains(
            "        if let Some(item) = LogicalAccessItem::scan(scan) {\n            self.metrics.logical_reads += slots;\n            self.logical_accesses.push(item);\n        }",
        )
        && recorder.matches("Item::scan(").count() == 2
        // The objects: a scan is recorded with one length only if every
        // slot has it, and a commit's seals are inside its rewrite.
        && objects.contains(
            "    let len = physical_slots.first().map_or(0, |slot| slot.len());\n    if physical_slots.iter().all(|slot| slot.len() == len) {\n        trace.physical_scan(object_name, kind, physical_slots.len(), len);\n        return;\n    }",
        )
        && objects.contains(
            "    for (index, slot) in physical_slots.iter().enumerate() {\n        trace.physical_read(object_name, slots.location(index), slot.len());\n    }",
        )
        && objects.contains(
            "        trace.physical_scan(\n            &self.spec.name,\n            ExactObjectKind::Cell,\n            1,\n            self.physical.len(),\n        );",
        )
        && objects.matches("trace.physical_scan(").count() == 2
        && objects.contains(
            "    trace.logical_scan(\"uomap_scan\", &object.spec.name, object.entries.len());",
        )
        && objects.matches("trace.logical_scan(").count() == 1
        && objects.matches("trace.begin_exact_rewrite(&spec_name, ExactObjectKind::").count() == 3
        && objects.matches("trace.begin_exact_rewrite(").count() == 3
        && objects.matches("                )?;\n                trace.end_exact_rewrite();").count() == 3
        && objects.matches("end_exact_rewrite(").count() == 3
        // No other runtime file names a run item's type or builds a run.
        && run_type_files.is_empty()
        && rewrite_files == TRACE_RUN_RECORDER_FILES
        && scan_files == TRACE_RUN_RECORDER_FILES
}

fn production_source_slice(source: &str) -> String {
    const CFG_TEST_ATTR: &str = "#[cfg(test)]";

    let bytes = source.as_bytes();
    let mut out = String::with_capacity(source.len());
    let mut cursor = 0;

    while let Some(relative) = source[cursor..].find(CFG_TEST_ATTR) {
        let start = cursor + relative;
        out.push_str(&source[cursor..start]);

        let mut i = start + CFG_TEST_ATTR.len();
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }

        while i + 1 < bytes.len() && bytes[i] == b'#' && bytes[i + 1] == b'[' {
            i += 2;
            while i < bytes.len() && bytes[i] != b']' {
                i += 1;
            }
            if i < bytes.len() {
                i += 1;
            }
            while i < bytes.len() && bytes[i].is_ascii_whitespace() {
                i += 1;
            }
        }

        let mut item_start = i;
        while item_start < bytes.len() && bytes[item_start].is_ascii_whitespace() {
            item_start += 1;
        }

        let mut item_end = item_start;
        while item_end < bytes.len() && bytes[item_end] != b'{' && bytes[item_end] != b';' {
            item_end += 1;
        }
        if item_end == bytes.len() {
            cursor = item_end;
            break;
        }
        if bytes[item_end] == b';' {
            cursor = item_end + 1;
            continue;
        }

        let mut depth = 1usize;
        item_end += 1;
        while item_end < bytes.len() && depth > 0 {
            match bytes[item_end] {
                b'{' => depth += 1,
                b'}' => depth -= 1,
                _ => {}
            }
            item_end += 1;
        }
        cursor = item_end;
    }

    out.push_str(&source[cursor..]);
    out
}

fn collect_production_pattern_hits(root: &Path, pattern: &str) -> Result<Vec<String>> {
    let mut files = Vec::new();
    collect_rust_source_files(root, &mut files)?;
    let mut hits = Vec::new();
    for path in files {
        let source =
            fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
        if production_source_slice(&source).contains(pattern) {
            hits.push(display_report_path(&path));
        }
    }
    hits.sort();
    Ok(hits)
}

fn source_contains_compact(source: &str, needle: &str) -> bool {
    let compact_source = source
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace())
        .collect::<String>();
    let compact_needle = needle
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace())
        .collect::<String>();
    compact_source.contains(&compact_needle)
}

fn rustfmt_temp_source_path(label: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock should be after unix epoch")
        .as_nanos();
    std::env::temp_dir().join(format!(
        "uo-probe-rustfmt-{}-{}-{}.rs",
        process::id(),
        sanitize_case_name(label),
        nanos
    ))
}

fn rustfmt_normalized_source(label: &str, source: &str) -> Result<String> {
    let path = rustfmt_temp_source_path(label);
    fs::write(&path, source).with_context(|| format!("writing {}", path.display()))?;
    let output = Command::new("rustfmt")
        .arg("--edition")
        .arg("2021")
        .arg(&path)
        .output()
        .with_context(|| format!("running rustfmt on {}", path.display()))?;
    if !output.status.success() {
        let _ = fs::remove_file(&path);
        return Err(anyhow!(
            "rustfmt failed for {}: {}",
            path.display(),
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    let normalized =
        fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
    let _ = fs::remove_file(&path);
    Ok(normalized)
}

fn rustfmt_equivalent_sources(label: &str, actual: &str, expected: &str) -> Result<bool> {
    let actual_normalized = rustfmt_normalized_source(&format!("{label}_actual"), actual)?;
    let expected_normalized = rustfmt_normalized_source(&format!("{label}_expected"), expected)?;
    Ok(actual_normalized == expected_normalized)
}

fn collect_production_compact_pattern_hits(root: &Path, pattern: &str) -> Result<Vec<String>> {
    let mut files = Vec::new();
    collect_rust_source_files(root, &mut files)?;
    let mut hits = Vec::new();
    for path in files {
        let source =
            fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
        if source_contains_compact(&production_source_slice(&source), pattern) {
            hits.push(display_report_path(&path));
        }
    }
    hits.sort();
    Ok(hits)
}

fn collect_lean_pattern_hits(root: &Path, pattern: &str) -> Result<Vec<String>> {
    let mut files = Vec::new();
    collect_lean_source_files(root, &mut files)?;
    let mut hits = Vec::new();
    for path in files {
        let source =
            fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
        if source.contains(pattern) {
            hits.push(display_report_path(&path));
        }
    }
    hits.sort();
    Ok(hits)
}

