fn run_trace_equivalence(suite: &BTreeMap<&'static str, BenchArtifacts>) -> Result<JsonValue> {
    let classifier_uo = run_fixed_classifier_experiment(&suite["FixedSlotClassifier"].uo)
        .context("trace_equivalence/FixedSlotClassifier/uo")?;
    let classifier_raw = optional_raw_experiment(
        run_fixed_classifier_experiment(&suite["FixedSlotClassifier"].raw)
            .context("trace_equivalence/FixedSlotClassifier/raw"),
    )?;
    let classifier_same_same = optional_raw_experiment(
        run_classifier_same_same(&suite["FixedSlotClassifier"].raw)
            .context("trace_equivalence/FixedSlotClassifier/raw-sameSame"),
    )?;
    let auth_uo =
        run_authscan_experiment(&suite["AuthScan"].uo).context("trace_equivalence/AuthScan/uo")?;
    let mixer_uo = run_mixer_key_experiment(&suite["ConfidentialMixer"].uo)
        .context("trace_equivalence/ConfidentialMixer/uo")?;
    let mixer_oram = run_mixer_key_experiment(
        suite["ConfidentialMixer"]
            .oram
            .as_ref()
            .ok_or_else(|| anyhow!("missing mixer oram"))?,
    )
    .context("trace_equivalence/ConfidentialMixer/oram")?;
    let erc20_uo = run_erc20_allowance_key_experiment(&suite["ERC20Lite"].uo)
        .context("trace_equivalence/ERC20Lite/uo")?;
    let erc20_oram = run_erc20_allowance_key_experiment(
        suite["ERC20Lite"]
            .oram
            .as_ref()
            .ok_or_else(|| anyhow!("missing erc20 oram"))?,
    )
    .context("trace_equivalence/ERC20Lite/oram")?;
    let erc20_private_posmap = run_erc20_transfer_experiment(
        suite["ERC20Lite"]
            .private_posmap
            .as_ref()
            .ok_or_else(|| anyhow!("missing erc20 private posmap"))?,
    )
    .context("trace_equivalence/ERC20Lite/oram_private_posmap")?;
    let registry_uo = run_registry_key_experiment(&suite["RegistryCRUD"].uo)
        .context("trace_equivalence/RegistryCRUD/uo")?;
    let mixer_sealed_uo = run_mixer_sealed_balance_experiment(&suite["ConfidentialMixer"].uo)
        .context("trace_equivalence/ConfidentialMixer/uo_encrypted_return")?;
    let mixer_sealed_oram = run_mixer_sealed_balance_experiment(
        suite["ConfidentialMixer"]
            .oram
            .as_ref()
            .ok_or_else(|| anyhow!("missing mixer oram"))?,
    )
    .context("trace_equivalence/ConfidentialMixer/oram_encrypted_return")?;
    let mixer_sealed_private_posmap = run_mixer_sealed_balance_experiment(
        suite["ConfidentialMixer"]
            .private_posmap
            .as_ref()
            .ok_or_else(|| anyhow!("missing mixer private posmap"))?,
    )
    .context("trace_equivalence/ConfidentialMixer/oram_private_posmap_encrypted_return")?;
    Ok(json!({
        "positive_control": {
            "benchmark": "FixedSlotClassifier",
            "raw": optional_trace_control_summary(&classifier_raw),
            "same_same": optional_trace_control_summary(&classifier_same_same),
        },
        "exact_uo": [
            trace_summary("FixedSlotClassifier", "uo", &classifier_uo),
            trace_summary("AuthScan", "uo", &auth_uo),
            trace_summary("ConfidentialMixer", "uo", &mixer_uo),
            trace_summary("ERC20Lite", "uo", &erc20_uo),
            trace_summary("RegistryCRUD", "uo", &registry_uo),
            trace_summary("ConfidentialMixer", "uo_encrypted_return", &mixer_sealed_uo),
        ],
        "computational_uo": [
            trace_summary("ConfidentialMixer", "oram", &mixer_oram),
            trace_summary("ERC20Lite", "oram", &erc20_oram),
            trace_summary("ERC20Lite", "oram_private_posmap", &erc20_private_posmap),
            trace_summary(
                "ConfidentialMixer",
                "oram_encrypted_return",
                &mixer_sealed_oram,
            ),
            trace_summary(
                "ConfidentialMixer",
                "oram_private_posmap_encrypted_return",
                &mixer_sealed_private_posmap,
            ),
        ],
    }))
}

fn leakage_max_auc(report: &JsonValue) -> Option<f64> {
    report
        .get("metric_auc")
        .and_then(|metrics| metrics.as_object())
        .map(|metrics| {
            metrics
                .values()
                .filter_map(|value| value.as_f64())
                .fold(0.0_f64, f64::max)
        })
}

/// Positive/negative/computational leakage controls (Issue 18). Insecure raw and
/// ct-gas-only baselines are positive controls that must leak above threshold;
/// exact UO backends are negative controls that must stay at/below the silent
/// threshold; ORAM backends are labeled computational (related only
/// computationally, so a silent observer AUC is expected, not an exact-equality
/// claim). The aggregate fails closed if a positive control does not leak or a
/// negative/computational control leaks above threshold.
fn leakage_controls(reports: &[JsonValue]) -> JsonValue {
    const LEAK_THRESHOLD: f64 = 0.9;
    const SILENT_THRESHOLD: f64 = 0.6;
    let mut positive = Vec::new();
    let mut negative = Vec::new();
    let mut computational = Vec::new();
    for report in reports {
        let Some(mode) = report.get("mode").and_then(|mode| mode.as_str()) else {
            continue;
        };
        let Some(max_auc) = leakage_max_auc(report) else {
            continue;
        };
        let benchmark = report
            .get("benchmark")
            .and_then(|benchmark| benchmark.as_str())
            .unwrap_or("");
        let entry = json!({ "benchmark": benchmark, "mode": mode, "max_auc": max_auc });
        match mode {
            "raw_insecure_eval" | "ct_gas_only" => positive.push(entry),
            "uo" => negative.push(entry),
            "oram" | "oram_private_posmap" => computational.push(entry),
            _ => {}
        }
    }
    let max_auc_of = |entry: &JsonValue| {
        entry
            .get("max_auc")
            .and_then(|value| value.as_f64())
            .unwrap_or(0.0)
    };
    let positive_controls_leak = positive
        .iter()
        .all(|entry| max_auc_of(entry) > LEAK_THRESHOLD);
    let negative_controls_silent = negative
        .iter()
        .all(|entry| max_auc_of(entry) <= SILENT_THRESHOLD);
    let computational_controls_silent = computational
        .iter()
        .all(|entry| max_auc_of(entry) <= SILENT_THRESHOLD);
    json!({
        "leak_threshold": LEAK_THRESHOLD,
        "silent_threshold": SILENT_THRESHOLD,
        "positive_controls": positive,
        "negative_controls": negative,
        "computational_controls": computational,
        "positive_controls_leak": positive_controls_leak,
        "negative_controls_silent": negative_controls_silent,
        "computational_controls_silent": computational_controls_silent,
        "accepted": positive_controls_leak
            && negative_controls_silent
            && computational_controls_silent,
    })
}

