/// Physical `(object, location)` trace the exact store's encoding predicts for
/// one run of a confidential kernel program. Rust mirror of `IR.exactEncodeRun`
/// in `proof/lean/UOToolchain/KernelExactTrace.lean`: the call reads every
/// slot of each object a statement accesses once, in object-id order, when it
/// loads the object, however many statements access it; and at commit every
/// object a statement writes is rewritten slot by slot, in object-id order,
/// with `Update`-class writes. An object the program only reads is not
/// written.
struct ExactEncodingPrediction {
    reads: Vec<(String, String)>,
    writes: Vec<(String, String)>,
    /// The length of a sealed slot of each object the program accesses: of a
    /// sealed value for a cell or an array, of a sealed map record for a
    /// map.
    record_lengths: BTreeMap<String, usize>,
}

/// Objects an expression reads, in evaluation order (`IR.KernelExpr.storageReads`).
/// `select` arms are pure, so only the condition can read storage.
fn exact_expr_storage_reads(expr: &ConfidentialKernelExpr, reads: &mut Vec<u32>) {
    match expr {
        ConfidentialKernelExpr::Literal { .. } | ConfidentialKernelExpr::Var { .. } => {}
        ConfidentialKernelExpr::Unary { expr, .. } => exact_expr_storage_reads(expr, reads),
        ConfidentialKernelExpr::Binary { lhs, rhs, .. } => {
            exact_expr_storage_reads(lhs, reads);
            exact_expr_storage_reads(rhs, reads);
        }
        ConfidentialKernelExpr::Select { cond, .. } => exact_expr_storage_reads(cond, reads),
        ConfidentialKernelExpr::CellGet { object_id } => reads.push(*object_id),
        ConfidentialKernelExpr::ArrayGet { object_id, index } => {
            exact_expr_storage_reads(index, reads);
            reads.push(*object_id);
        }
        ConfidentialKernelExpr::MapGet { object_id, key } => {
            exact_expr_storage_reads(key, reads);
            reads.push(*object_id);
        }
        ConfidentialKernelExpr::StructField { base, .. } => exact_expr_storage_reads(base, reads),
        ConfidentialKernelExpr::ArrayIndex { base, index } => {
            exact_expr_storage_reads(base, reads);
            exact_expr_storage_reads(index, reads);
        }
        ConfidentialKernelExpr::Keccak256 { parts } => {
            for part in parts.iter() {
                exact_expr_storage_reads(part, reads);
            }
        }
    }
}

/// Objects a statement accesses (`IR.KernelStatement.accesses`): the reads of
/// its expressions, then its write target, which also goes to `written`
/// (`IR.writtenObjects`), whatever the write's predicate.
fn exact_statement_accesses(
    statement: &ConfidentialKernelStatement,
    accesses: &mut Vec<u32>,
    written: &mut Vec<u32>,
) {
    match statement {
        ConfidentialKernelStatement::Declare { value, .. }
        | ConfidentialKernelStatement::Assign { value, .. } => {
            exact_expr_storage_reads(value, accesses)
        }
        ConfidentialKernelStatement::Require { cond }
        | ConfidentialKernelStatement::AbortIf { cond } => exact_expr_storage_reads(cond, accesses),
        ConfidentialKernelStatement::CellSet {
            object_id,
            value,
            predicate,
        } => {
            exact_expr_storage_reads(value, accesses);
            if let Some(predicate) = predicate {
                exact_expr_storage_reads(predicate, accesses);
            }
            accesses.push(*object_id);
            written.push(*object_id);
        }
        ConfidentialKernelStatement::ArraySet {
            object_id,
            index,
            value,
            predicate,
        } => {
            exact_expr_storage_reads(index, accesses);
            exact_expr_storage_reads(value, accesses);
            if let Some(predicate) = predicate {
                exact_expr_storage_reads(predicate, accesses);
            }
            accesses.push(*object_id);
            written.push(*object_id);
        }
        ConfidentialKernelStatement::MapPut {
            object_id,
            key,
            value,
            predicate,
        } => {
            exact_expr_storage_reads(key, accesses);
            exact_expr_storage_reads(value, accesses);
            if let Some(predicate) = predicate {
                exact_expr_storage_reads(predicate, accesses);
            }
            accesses.push(*object_id);
            written.push(*object_id);
        }
        ConfidentialKernelStatement::Return { value } => {
            if let Some(value) = value {
                exact_expr_storage_reads(value, accesses);
            }
        }
    }
}

/// The exact-store encoding's prediction for one run of `entrypoint`, or `None`
/// when the entrypoint is not a confidential UO kernel program or an accessed
/// object is not on an exact (full-scan) backend.
fn exact_encoding_prediction(
    artifact: &CompiledArtifact,
    entrypoint: &str,
) -> Option<ExactEncodingPrediction> {
    if artifact.contract.mode != ProgramMode::Uo {
        return None;
    }
    let function = artifact
        .contract
        .functions
        .iter()
        .find(|function| function.signature == entrypoint)?;
    let program = function.confidential_program.as_ref()?;
    let mut accesses = Vec::new();
    let mut written = Vec::new();
    for statement in program.body.iter() {
        exact_statement_accesses(statement, &mut accesses, &mut written);
    }
    let mut record_lengths = BTreeMap::new();
    let mut slot_locations = |object_id: u32| -> Option<(String, Vec<String>)> {
        let object = artifact
            .contract
            .state
            .iter()
            .find(|object| object.id == object_id)?;
        if object.backend != BackendKind::FullScan {
            return None;
        }
        let value_len = object.value_type.canonical_len();
        let (locations, payload_len) = match object.kind {
            ContainerKind::Cell => (vec![object.name.clone()], value_len),
            ContainerKind::Array => (
                (0..object.capacity?)
                    .map(|slot| format!("{}[{}]", object.name, slot))
                    .collect(),
                value_len,
            ),
            ContainerKind::Map => (
                (0..object.capacity?)
                    .map(|slot| format!("{}#{}", object.name, slot))
                    .collect(),
                1 + object.key_type.as_ref()?.canonical_len() + value_len,
            ),
        };
        record_lengths.insert(object.name.clone(), sealed_encoded_len(payload_len));
        Some((object.name.clone(), locations))
    };
    // `IR.touchedObjects`: each accessed object once, in increasing id order.
    let mut touched = accesses;
    touched.sort_unstable();
    touched.dedup();
    let mut reads = Vec::new();
    for object_id in touched {
        let (name, locations) = slot_locations(object_id)?;
        reads.extend(
            locations
                .into_iter()
                .map(|location| (name.clone(), location)),
        );
    }
    written.sort_unstable();
    written.dedup();
    let mut writes = Vec::new();
    for object_id in written {
        let (name, locations) = slot_locations(object_id)?;
        writes.extend(
            locations
                .into_iter()
                .map(|location| (name.clone(), location)),
        );
    }
    Some(ExactEncodingPrediction {
        reads,
        writes,
        record_lengths,
    })
}

/// Whether a runtime trace is the predicted one: the same `(object, location)`
/// reads and writes in order, only `Update`-class writes, and every record
/// of the length of its object's sealed slot. The trace holds the scan and
/// the rewrite of an object as one item each; this compares their events,
/// so a scan of another number of slots or of another length is not the
/// predicted one.
fn trace_matches_exact_encoding(
    trace: &uo_core::ExecutionTrace,
    prediction: &ExactEncodingPrediction,
) -> bool {
    let reads = trace
        .physical_reads
        .events()
        .map(|event| (event.object.clone(), event.location.clone()))
        .collect::<Vec<_>>();
    let writes = trace
        .physical_writes
        .events()
        .map(|event| (event.object.clone(), event.location.clone()))
        .collect::<Vec<_>>();
    let lengths_predicted = trace
        .physical_reads
        .events()
        .map(|event| (event.object, event.len))
        .chain(
            trace
                .physical_writes
                .events()
                .map(|event| (event.object, event.len)),
        )
        .all(|(object, len)| prediction.record_lengths.get(&object) == Some(&len));
    reads == prediction.reads
        && writes == prediction.writes
        && trace
            .physical_writes
            .events()
            .all(|event| event.class == WriteClass::Update)
        && lengths_predicted
}

/// Tamper scenarios on the trace of an exact-backend call. The trace holds
/// the scan of a full-scan map and its rewrite as one item each, with the
/// map's slot count and the length of a sealed record. A trace whose item
/// names another count or another length is not the trace the exact store's
/// encoding predicts from the artifact, and the check that compares the two
/// rejects it.
fn exact_trace_run_tamper_scenarios() -> Result<Vec<JsonValue>> {
    use uo_core::{PhysicalReadItem, PhysicalWriteItem};
    let artifact = compile_artifact(
        "benches/raw/ConfidentialMixer.sol",
        "benches/raw/ConfidentialMixer.uo.yaml",
        ProgramMode::Uo,
    )?;
    let entrypoint = "deposit(bytes32,uint256)";
    let prediction = exact_encoding_prediction(&artifact, entrypoint)
        .ok_or_else(|| anyhow!("{entrypoint} is not on the exact route"))?;
    let run = || run_target_call(&artifact, &[], entrypoint, vec![b32(7), Value::uint(5)]);
    let honest = run()?;
    if !trace_matches_exact_encoding(&honest, &prediction) {
        bail!("the trace of {entrypoint} is not the exact store's encoding");
    }
    let scan_of = |trace: &uo_core::ExecutionTrace| {
        trace
            .physical_reads
            .items()
            .iter()
            .position(|item| matches!(item, PhysicalReadItem::Scan(_)))
            .ok_or_else(|| anyhow!("the trace of {entrypoint} holds no scan"))
    };
    let rewrite_of = |trace: &uo_core::ExecutionTrace| {
        trace
            .physical_writes
            .items()
            .iter()
            .position(|item| matches!(item, PhysicalWriteItem::Rewrite(_)))
            .ok_or_else(|| anyhow!("the trace of {entrypoint} holds no rewrite"))
    };
    type Mutation = fn(&mut uo_core::ExactObjectSlots);
    let cases: [(&str, &str, bool, bool, Mutation); 4] = [
        (
            "exact_trace/scan_slot_count_drift",
            "name one slot fewer in the scan of the full-scan map than the map has, so the check of the trace against the exact store's encoding must reject a scan that leaves a slot out",
            true,
            false,
            |run| run.slots -= 1,
        ),
        (
            "exact_trace/rewrite_slot_count_drift",
            "name one slot more in the rewrite of the full-scan map than the map has, so the check of the trace against the exact store's encoding must reject a rewrite of another number of slots",
            false,
            true,
            |run| run.slots += 1,
        ),
        (
            "exact_trace/scan_record_length_drift",
            "name another record length in the scan of the full-scan map and in its rewrite, the same in both, so the check of the trace against the exact store's encoding must reject records that are not of the length of the map's sealed slot",
            true,
            true,
            |run| run.len -= 32,
        ),
        (
            "exact_trace/scan_slot_naming_drift",
            "name the slots of the full-scan map as those of an array in its scan, so the check of the trace against the exact store's encoding must reject a scan of other locations",
            true,
            false,
            |run| run.kind = uo_core::ExactObjectKind::Array,
        ),
    ];
    let mut scenarios = Vec::with_capacity(cases.len());
    for (scenario, mutation, in_scan, in_rewrite, mutate) in cases {
        let mut trace = run()?;
        if in_scan {
            let index = scan_of(&trace)?;
            if let PhysicalReadItem::Scan(item) = &mut trace.physical_reads.items_mut()[index] {
                mutate(&mut item.scan);
            }
        }
        if in_rewrite {
            let index = rewrite_of(&trace)?;
            if let PhysicalWriteItem::Rewrite(item) = &mut trace.physical_writes.items_mut()[index]
            {
                mutate(&mut item.rewrite);
            }
        }
        if trace.receipt == honest.receipt {
            bail!("{scenario} changed nothing");
        }
        let accepted = trace_matches_exact_encoding(&trace, &prediction);
        scenarios.push(json!({
            "scenario": scenario,
            "artifact_kind": "runtime_exact_trace",
            "benchmark": "ConfidentialMixer/uo/deposit",
            "entrypoint": entrypoint,
            "mutation": mutation,
            "accepted": accepted,
            "rejected": !accepted,
            "error": if accepted {
                "unexpectedly accepted a trace that is not the exact store's encoding"
            } else {
                "the trace is not the exact store's encoding of the entrypoint"
            },
        }));
    }
    Ok(scenarios)
}

/// The trace route of a confidential kernel program, as `checkKernelAdmission`
/// reports it (`traceRoute` in `UOToolchain/KernelAdmission.lean`): exact when
/// every object it accesses is on a full-scan backend, Path ORAM when the
/// others are on an ORAM backend. The Lean models of the public outcome, the
/// boundary schedule, and the final public-state record cover both routes
/// (`UOToolchain/KernelPaperMain.lean` and
/// `UOToolchain/PathOramKernelPaperMain.lean`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum KernelTraceRoute {
    Exact,
    PathOram,
}

/// `None` when the entrypoint is not a confidential kernel program of a UO
/// build or accesses a raw object.
fn kernel_trace_route(artifact: &CompiledArtifact, entrypoint: &str) -> Option<KernelTraceRoute> {
    if artifact.contract.mode != ProgramMode::Uo {
        return None;
    }
    let function = artifact
        .contract
        .functions
        .iter()
        .find(|function| function.signature == entrypoint)?;
    let program = function.confidential_program.as_ref()?;
    let mut accesses = Vec::new();
    for statement in program.body.iter() {
        exact_statement_accesses(statement, &mut accesses, &mut Vec::new());
    }
    let mut route = KernelTraceRoute::Exact;
    for object_id in accesses {
        let object = artifact
            .contract
            .state
            .iter()
            .find(|object| object.id == object_id)?;
        match object.backend {
            BackendKind::FullScan => {}
            BackendKind::Oram => route = KernelTraceRoute::PathOram,
            BackendKind::Raw => return None,
        }
    }
    Some(route)
}

/// What the Lean models of a run's public observables (`kernelPublicOutcome`
/// and `kernelBoundarySchedule` in `UOToolchain/KernelPaperMain.lean`,
/// `kernelOramBoundarySchedule` in `UOToolchain/PathOramKernelPaperMain.lean`)
/// take from the artifact.
struct KernelOutcomeModel {
    entry_input_len: usize,
    return_length: usize,
    returns_value: bool,
    /// The entrypoint returns its value encrypted to the client
    /// (`returns: encrypted_to_client`).
    encrypted_return: bool,
    gas: u64,
    /// The call's ORAM accesses: the manifest's per-object counts, which the
    /// program and its maps' schemes fix; none on the exact route.
    oram_accesses: usize,
}

fn kernel_outcome_model(
    artifact: &CompiledArtifact,
    entrypoint: &str,
    route: KernelTraceRoute,
) -> Option<KernelOutcomeModel> {
    let entry = artifact.contract.manifest.entrypoints.get(entrypoint)?;
    let program = entry.confidential_program.as_ref()?;
    let oram_accesses = entry.oram_accesses.values().sum::<usize>();
    if (route == KernelTraceRoute::PathOram) != (oram_accesses > 0) {
        return None;
    }
    Some(KernelOutcomeModel {
        entry_input_len: entry.entry_input_len,
        return_length: entry.return_canonical_len.unwrap_or(0),
        returns_value: matches!(
            program.body.last(),
            Some(ConfidentialKernelStatement::Return { value: Some(_) })
        ),
        encrypted_return: entry.returns == uo_core::ReturnPolicy::EncryptedToClient,
        gas: entry.public_gas_budget,
        oram_accesses,
    })
}

/// The bytes an encrypted return adds to the canonical bytes of its value:
/// a 12-byte nonce and a 16-byte tag (`returnChannelOverheadBytes` in
/// `UOToolchain/KernelPaperMain.lean`).
const RETURN_CHANNEL_OVERHEAD_BYTES: usize = 28;

impl KernelOutcomeModel {
    /// What a call that returns a value hands the host
    /// (`EntrypointPublicPolicy.outputLength`).
    fn output_length(&self) -> usize {
        if self.encrypted_return {
            self.return_length + RETURN_CHANNEL_OVERHEAD_BYTES
        } else {
            self.return_length
        }
    }
}

/// Whether a run's public outcome and boundary schedule are the modeled ones.
/// A run that completes with a return value has the declared return length as
/// its output shape and exit length; any other run, an abort or a completed
/// call without a return value, has the empty output shape and exits with
/// nothing. The gas is the entrypoint's modeled cost either way. Between the
/// entry and the exit, the call leaves and re-enters the enclave around each of
/// its ORAM accesses, completed or not. A value returned under
/// `encrypted_to_client` is in the outcome as its encrypted payload, of the
/// declared plaintext length and of the wire length the exit has, and not in
/// the clear; under any other policy the outcome holds it in the clear and
/// no encrypted payload.
fn run_matches_outcome_model(
    trace: &uo_core::ExecutionTrace,
    entrypoint: &str,
    model: &KernelOutcomeModel,
) -> bool {
    let Ok(certificate) = trace.runtime_controller_observer_certificate() else {
        return false;
    };
    let outcome = certificate.public_outcome();
    let returned = outcome.termination_status && model.returns_value;
    let shape = if returned {
        uo_core::OutputShape::returned(model.output_length())
    } else {
        uo_core::OutputShape::default()
    };
    let payloads_as_modeled = if model.encrypted_return {
        outcome.return_payload.is_none()
            && outcome.encrypted_return_payload.is_some() == returned
            && outcome
                .encrypted_return_payload
                .as_ref()
                .is_none_or(|payload| {
                    payload.plaintext_canonical_len == model.return_length
                        && payload.wire_len == model.output_length()
                })
    } else {
        outcome.return_payload.is_some() == returned && outcome.encrypted_return_payload.is_none()
    };
    let mut schedule = Vec::with_capacity(2 * model.oram_accesses + 2);
    schedule.push(BoundaryEvent::enter(entrypoint, model.entry_input_len));
    for _ in 0..model.oram_accesses {
        schedule.push(BoundaryEvent::exit("oram_access", 0));
        schedule.push(BoundaryEvent::enter("oram_access", 0));
    }
    schedule.push(BoundaryEvent::exit(entrypoint, shape.return_length));
    outcome.entrypoint_id == entrypoint
        && outcome.output_shape == shape
        && payloads_as_modeled
        && outcome.gas_used == model.gas
        && certificate.boundary_schedule() == schedule.as_slice()
}

/// Whether a run's final public-state record is the modeled one
/// (`kernelFinalPublicState` in `UOToolchain/KernelPaperMain.lean`). An admitted
/// program writes only confidential objects, so the model's initial, candidate,
/// and committed states are all the public state before the call, and its
/// public delta is empty; the abort flag is the negated termination status.
/// The digests are the runtime's: `public_state_before` and
/// `public_state_after` are the committed public state's digest just before
/// and just after the call.
fn run_matches_final_public_state_model(
    trace: &uo_core::ExecutionTrace,
    public_state_before: &str,
    public_state_after: &str,
) -> bool {
    let Some(record) = trace.public_state_transition.as_ref() else {
        return false;
    };
    let Ok(certificate) = trace.runtime_controller_observer_certificate() else {
        return false;
    };
    let Ok(empty_delta) = uo_core::public_delta_digest(&[]) else {
        return false;
    };
    record.initial_public_state_hash == public_state_before
        && record.candidate_public_state_hash == public_state_before
        && record.committed_public_state_hash == public_state_before
        && public_state_after == public_state_before
        && record.public_delta_hash == empty_delta
        && record.aborted != certificate.public_outcome().termination_status
}

/// A target call's result, with the committed public state's digest just
/// before and just after it.
struct PublicStateBracketedCall {
    result: DiagnosticCallResult,
    public_state_before: String,
    public_state_after: String,
}

fn run_target_call_with_public_state(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &str,
    args: Vec<Value>,
    return_channel: Option<&ReturnChannelSession>,
) -> Result<PublicStateBracketedCall> {
    let mut instance = ContractInstance::deploy_with_seed(artifact.clone(), PROBE_DEPLOY_SEED)?;
    for call in setup {
        instance.call(call.entrypoint, call.args.clone())?;
    }
    let public_state_before = instance.public_state_digest()?;
    let result = match return_channel {
        Some(session) => {
            instance.call_with_return_channel_diagnostics(entrypoint, args, session)?
        }
        None => instance.call_with_diagnostics(entrypoint, args)?,
    };
    let public_state_after = instance.public_state_digest()?;
    Ok(PublicStateBracketedCall {
        result,
        public_state_before,
        public_state_after,
    })
}

fn run_binary_experiment(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &'static str,
    class0: Vec<Vec<Value>>,
    class1: Vec<Vec<Value>>,
) -> Result<ExperimentOutcome> {
    run_binary_experiment_on_channel(artifact, setup, entrypoint, class0, class1, None)
}

/// What the runs of an `encrypted_to_client` entrypoint show of its return
/// channel. The Lean model of the channel (`ReturnChannelModel` in
/// `UOToolchain/KernelPaperMain.lean`) takes a payload without its AEAD
/// output to be fixed by the call's public arguments; here the runs differ
/// in their secrets alone.
#[derive(Clone, Debug, Serialize)]
struct EncryptedReturnChecks {
    /// Runs that returned an encrypted payload.
    runs: usize,
    /// Every payload opens under the caller's session, with the associated
    /// data the caller builds from the public facts of the call.
    every_return_opens_for_the_session: bool,
    /// No payload opens under another key.
    no_return_opens_under_another_key: bool,
    /// The session binding, the hash of the associated data, the nonce and
    /// the two lengths are the same in every run.
    frame_same_in_every_run: bool,
    /// No outcome and no call result holds the returned value in the clear.
    no_plaintext_return: bool,
    /// The values the caller opened, how many of them differ.
    distinct_returned_values: usize,
    /// Runs that returned different values returned different ciphertexts
    /// and tags: the AEAD output is what the policy releases.
    ciphertext_differs_with_the_value: bool,
}

impl EncryptedReturnChecks {
    fn hold(&self) -> bool {
        self.runs > 0
            && self.every_return_opens_for_the_session
            && self.no_return_opens_under_another_key
            && self.frame_same_in_every_run
            && self.no_plaintext_return
            && self.ciphertext_differs_with_the_value
    }
}

/// The checks of `EncryptedReturnChecks` over the results of an experiment's
/// runs.
fn encrypted_return_checks(
    artifact: &CompiledArtifact,
    entrypoint: &str,
    session: &ReturnChannelSession,
    results: &[DiagnosticCallResult],
) -> Result<EncryptedReturnChecks> {
    let other_key = ReturnChannelSession::new([0xa7; 32], session.binding().clone())?;
    let mut opened = Vec::new();
    let mut frames = Vec::new();
    let mut every_return_opens_for_the_session = true;
    let mut no_return_opens_under_another_key = true;
    let mut no_plaintext_return = true;
    for result in results {
        let certificate = result
            .call
            .trace
            .runtime_controller_observer_certificate()?;
        let outcome = certificate.public_outcome();
        no_plaintext_return &=
            result.call.return_value.is_none() && outcome.return_payload.is_none();
        let Some(payload) = outcome.encrypted_return_payload.as_ref() else {
            continue;
        };
        no_plaintext_return &= result.call.encrypted_return.as_ref() == Some(payload);
        frames.push((
            payload.binding.clone(),
            payload.aad_hash.clone(),
            payload.nonce.clone(),
            payload.plaintext_canonical_len,
            payload.wire_len,
        ));
        match open_encrypted_return(artifact, entrypoint, &outcome.public_args, payload, session) {
            Ok(value) => opened.push((value, payload.ciphertext.clone(), payload.tag.clone())),
            Err(_) => every_return_opens_for_the_session = false,
        }
        no_return_opens_under_another_key &= open_encrypted_return(
            artifact,
            entrypoint,
            &outcome.public_args,
            payload,
            &other_key,
        )
        .is_err();
    }
    let distinct_returned_values = opened
        .iter()
        .map(|(value, _, _)| value)
        .collect::<BTreeSet<_>>()
        .len();
    let ciphertext_differs_with_the_value = opened.iter().enumerate().all(|(index, lhs)| {
        opened
            .iter()
            .skip(index + 1)
            .all(|rhs| lhs.0 == rhs.0 || (lhs.1 != rhs.1 && lhs.2 != rhs.2))
    });
    Ok(EncryptedReturnChecks {
        runs: frames.len(),
        every_return_opens_for_the_session,
        no_return_opens_under_another_key,
        frame_same_in_every_run: frames.windows(2).all(|pair| pair[0] == pair[1]),
        no_plaintext_return,
        distinct_returned_values,
        ciphertext_differs_with_the_value: distinct_returned_values > 1
            && ciphertext_differs_with_the_value,
    })
}

/// `run_binary_experiment` for an entrypoint that may return on a return
/// channel: with a session, every target call is made with it, and the
/// outcome reports what the runs show of the channel.
fn run_binary_experiment_on_channel(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &'static str,
    class0: Vec<Vec<Value>>,
    class1: Vec<Vec<Value>>,
    return_channel: Option<&ReturnChannelSession>,
) -> Result<ExperimentOutcome> {
    let prediction = exact_encoding_prediction(artifact, entrypoint);
    let mut exact_encoding_matches = prediction.as_ref().map(|_| true);
    let route = kernel_trace_route(artifact, entrypoint);
    let outcome_model = route.and_then(|route| kernel_outcome_model(artifact, entrypoint, route));
    let mut outcome_model_matches = route.map(|_| outcome_model.is_some());
    let mut final_public_state_model_matches = route.map(|_| true);
    let mut metrics = [Vec::new(), Vec::new()];
    let mut hashes = [Vec::new(), Vec::new()];
    let mut results = Vec::new();
    for (class, runs) in [class0, class1].into_iter().enumerate() {
        for args in runs {
            let bracketed = run_target_call_with_public_state(
                artifact,
                setup,
                entrypoint,
                args,
                return_channel,
            )?;
            let result = bracketed.result;
            if let (Some(prediction), Some(matches)) =
                (prediction.as_ref(), exact_encoding_matches.as_mut())
            {
                *matches &= trace_matches_exact_encoding(&result.call.trace, prediction);
            }
            if let (Some(model), Some(matches)) =
                (outcome_model.as_ref(), outcome_model_matches.as_mut())
            {
                *matches &= run_matches_outcome_model(&result.call.trace, entrypoint, model);
            }
            if let Some(matches) = final_public_state_model_matches.as_mut() {
                *matches &= run_matches_final_public_state_model(
                    &result.call.trace,
                    &bracketed.public_state_before,
                    &bracketed.public_state_after,
                );
            }
            hashes[class].push(result.call.trace.hashes()?);
            metrics[class].push(extract_metrics(&result));
            results.push(result);
        }
    }
    let encrypted_return = return_channel
        .map(|session| encrypted_return_checks(artifact, entrypoint, session, &results))
        .transpose()?;
    let [class0_hashes, class1_hashes] = hashes;
    let [class0_metrics, class1_metrics] = metrics;
    Ok(ExperimentOutcome {
        exact_encoding_matches,
        outcome_model_matches,
        final_public_state_model_matches,
        encrypted_return,
        opcode_equal: hashes_equal(&class0_hashes, &class1_hashes, |hash| {
            &hash.opcode_trace_hash
        }),
        logical_equal: hashes_equal(&class0_hashes, &class1_hashes, |hash| {
            &hash.logical_access_trace_hash
        }),
        logical_write_equal: hashes_equal(&class0_hashes, &class1_hashes, |hash| {
            &hash.logical_write_trace_hash
        }),
        physical_read_equal: hashes_equal(&class0_hashes, &class1_hashes, |hash| {
            &hash.physical_read_trace_hash
        }),
        physical_equal: hashes_equal(&class0_hashes, &class1_hashes, |hash| {
            &hash.physical_access_trace_hash
        }),
        class0_metrics,
        class1_metrics,
    })
}

fn run_target_call_with_diagnostics(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &str,
    args: Vec<Value>,
) -> Result<DiagnosticCallResult> {
    let mut instance = ContractInstance::deploy_with_seed(artifact.clone(), PROBE_DEPLOY_SEED)?;
    for call in setup {
        instance.call(call.entrypoint, call.args.clone())?;
    }
    instance.call_with_diagnostics(entrypoint, args)
}

fn experiment_metric_summary<F>(
    benchmark: &str,
    mode: &str,
    metric_field: &str,
    result: Result<ExperimentOutcome>,
    metric_report: F,
) -> Result<JsonValue>
where
    F: FnOnce(&[BTreeMap<String, f64>], &[BTreeMap<String, f64>]) -> JsonValue,
{
    match result {
        Ok(experiment) => {
            let mut entry = serde_json::Map::new();
            entry.insert("benchmark".into(), json!(benchmark));
            entry.insert("mode".into(), json!(mode));
            entry.insert("executable".into(), json!(true));
            entry.insert("rejected".into(), json!(false));
            entry.insert(
                metric_field.into(),
                metric_report(&experiment.class0_metrics, &experiment.class1_metrics),
            );
            Ok(JsonValue::Object(entry))
        }
        Err(err) if mode == "raw" && is_expected_confidential_raw_backend_rejection(&err) => {
            Ok(json!({
                "benchmark": benchmark,
                "mode": mode,
                "executable": false,
                "rejected": true,
                "error": err.to_string(),
            }))
        }
        Err(err) => Err(err),
    }
}

fn raw_eval_mode_label() -> &'static str {
    if cfg!(feature = "insecure-eval-raw") {
        "raw_insecure_eval"
    } else {
        "raw"
    }
}

fn optional_raw_experiment(result: Result<ExperimentOutcome>) -> Result<OptionalExperimentOutcome> {
    match result {
        Ok(experiment) => Ok(OptionalExperimentOutcome::Executed(experiment)),
        Err(err) if is_expected_confidential_raw_backend_rejection(&err) => {
            Ok(OptionalExperimentOutcome::Rejected {
                error: err.to_string(),
            })
        }
        Err(err) => Err(err),
    }
}

fn optional_trace_control_summary(result: &OptionalExperimentOutcome) -> JsonValue {
    match result {
        OptionalExperimentOutcome::Executed(experiment) => json!({
            "executable": true,
            "rejected": false,
            "opcode_equal": experiment.opcode_equal,
            "logical_access_equal": experiment.logical_equal,
            "logical_write_equal": experiment.logical_write_equal,
            "physical_read_equal": experiment.physical_read_equal,
            "physical_equal": experiment.physical_equal,
        }),
        OptionalExperimentOutcome::Rejected { error } => json!({
            "executable": false,
            "rejected": true,
            "error": error,
        }),
    }
}

fn run_target_call(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &str,
    args: Vec<Value>,
) -> Result<uo_core::ExecutionTrace> {
    Ok(
        run_target_call_with_diagnostics(artifact, setup, entrypoint, args)?
            .call
            .trace,
    )
}

fn exact_confidential_kernel_witness(
    trace: &uo_core::ExecutionTrace,
    artifact: &CompiledArtifact,
    entrypoint: &str,
) -> Result<Option<RuntimeKernelWitness>> {
    let function = artifact
        .contract
        .functions
        .iter()
        .find(|function| function.signature == entrypoint)
        .ok_or_else(|| anyhow!("artifact is missing entrypoint {}", entrypoint))?;
    if !function.confidential {
        return Ok(None);
    }
    Ok(Some(trace.runtime_kernel_witness_for_confidential(
        artifact, entrypoint,
    )?))
}

fn kernel_witness_summary(kernel_witness: Option<&RuntimeKernelWitness>) -> JsonValue {
    match kernel_witness {
        Some(kernel_witness) => json!({
            "present": true,
            "entrypoint": kernel_witness.entrypoint_id(),
            "kernel_op_count": kernel_witness.kernel_steps().len(),
            "public_object_universe": kernel_witness.emitted_public_object_schedule(),
            "expected_public_object_universe": kernel_witness.expected_public_object_schedule(),
            "canonical_loaded_object_schedule": kernel_witness.canonical_loaded_object_schedule(),
            "kernel_step_public_object_schedule": kernel_witness.emitted_kernel_schedule().public_object_schedule(),
            "expected_kernel_step_public_object_schedule": kernel_witness.expected_kernel_schedule().map(|schedule| schedule.public_object_schedule()),
            "shell_contract": {
                "public_object_universe": kernel_witness.emitted_public_object_schedule(),
                "canonical_loaded_object_schedule": kernel_witness.canonical_loaded_object_schedule(),
                "kernel_step_public_object_schedule": kernel_witness.emitted_kernel_schedule().public_object_schedule(),
            },
            "resource_event_count": kernel_witness.resource_events().event_count(),
            "resource_events": kernel_witness.resource_events(),
            "claimed_resource_state": {
                "peak_stack_words": kernel_witness.peak_stack_words(),
                "value_scratch": {
                    "live_bytes": kernel_witness.value_scratch_live_bytes_end(),
                    "peak_bytes": kernel_witness.value_scratch_peak_bytes(),
                    "wipe_count": kernel_witness.value_scratch_wipe_count(),
                },
                "hash_scratch": {
                    "live_bytes": kernel_witness.hash_scratch_live_bytes_end(),
                    "peak_bytes": kernel_witness.hash_scratch_peak_bytes(),
                    "wipe_count": kernel_witness.hash_scratch_wipe_count(),
                },
                "io_scratch": {
                    "live_bytes": kernel_witness.io_scratch_live_bytes_end(),
                    "peak_bytes": kernel_witness.io_scratch_peak_bytes(),
                    "wipe_count": kernel_witness.io_scratch_wipe_count(),
                },
            },
            "peak_stack_words": kernel_witness.peak_stack_words(),
            "value_scratch_peak_bytes": kernel_witness.value_scratch_peak_bytes(),
            "value_scratch_wipe_count": kernel_witness.value_scratch_wipe_count(),
            "hash_scratch_peak_bytes": kernel_witness.hash_scratch_peak_bytes(),
            "hash_scratch_wipe_count": kernel_witness.hash_scratch_wipe_count(),
            "io_scratch_peak_bytes": kernel_witness.io_scratch_peak_bytes(),
            "io_scratch_wipe_count": kernel_witness.io_scratch_wipe_count(),
        }),
        None => json!({
            "present": false,
        }),
    }
}

fn runtime_kernel_refinement_witness_summary(
    runtime_kernel_refinement_witness: Option<&RuntimeKernelRefinementWitness>,
    kernel_witness: Option<&RuntimeKernelWitness>,
) -> JsonValue {
    match runtime_kernel_refinement_witness {
        Some(runtime_kernel_refinement_witness) => {
            let projected_kernel_schedule =
                runtime_kernel_refinement_witness.projected_kernel_schedule();
            let shadow_load_object_schedule =
                runtime_kernel_refinement_witness.shadow_load_object_schedule();
            let commit_object_schedule = runtime_kernel_refinement_witness.commit_object_schedule();
            let cold_store_object_schedule =
                runtime_kernel_refinement_witness.cold_store_object_schedule();
            let pre_committed_cold_object_schedule =
                runtime_kernel_refinement_witness.pre_committed_cold_object_schedule();
            let post_committed_cold_object_schedule =
                runtime_kernel_refinement_witness.post_committed_cold_object_schedule();
            let refines_shell_contract = kernel_witness.map(|kernel_witness| {
                projected_kernel_schedule == kernel_witness.emitted_kernel_schedule()
                    && pre_committed_cold_object_schedule.as_ref()
                        == kernel_witness.emitted_public_object_schedule()
                    && post_committed_cold_object_schedule.as_ref()
                        == kernel_witness.emitted_public_object_schedule()
                    && shadow_load_object_schedule.as_ref()
                        == kernel_witness.canonical_loaded_object_schedule().as_ref()
                    && commit_object_schedule.as_ref()
                        == kernel_witness.canonical_loaded_object_schedule().as_ref()
                    && cold_store_object_schedule.as_ref()
                        == kernel_witness.canonical_loaded_object_schedule().as_ref()
            });
            json!({
                "present": true,
                "event_count": runtime_kernel_refinement_witness.event_count(),
                "projected_kernel_step_count": projected_kernel_schedule.steps().len(),
                "projected_kernel_step_public_object_schedule": projected_kernel_schedule.public_object_schedule(),
                "pre_committed_cold_object_schedule": pre_committed_cold_object_schedule,
                "post_committed_cold_object_schedule": post_committed_cold_object_schedule,
                "shadow_load_object_schedule": shadow_load_object_schedule,
                "commit_object_schedule": commit_object_schedule,
                "cold_store_object_schedule": cold_store_object_schedule,
                "public_object_universe": kernel_witness
                    .map(RuntimeKernelWitness::emitted_public_object_schedule),
                "canonical_loaded_object_schedule": kernel_witness
                    .map(RuntimeKernelWitness::canonical_loaded_object_schedule),
                "shell_contract": kernel_witness.map(|kernel_witness| json!({
                    "public_object_universe": kernel_witness.emitted_public_object_schedule(),
                    "canonical_loaded_object_schedule": kernel_witness.canonical_loaded_object_schedule(),
                    "kernel_step_public_object_schedule": kernel_witness.emitted_kernel_schedule().public_object_schedule(),
                })),
                "projection_matches_kernel_witness": kernel_witness
                    .map(|kernel_witness| projected_kernel_schedule == kernel_witness.emitted_kernel_schedule()),
                "matches_canonical_kernel_object_schedule": kernel_witness.map(|kernel_witness| {
                    shadow_load_object_schedule.as_ref()
                        == kernel_witness.canonical_loaded_object_schedule().as_ref()
                }),
                "matches_public_object_universe_pre_boundary": kernel_witness.map(|kernel_witness| {
                    pre_committed_cold_object_schedule.as_ref()
                        == kernel_witness.emitted_public_object_schedule()
                }),
                "matches_public_object_universe_post_boundary": kernel_witness.map(|kernel_witness| {
                    post_committed_cold_object_schedule.as_ref()
                        == kernel_witness.emitted_public_object_schedule()
                }),
                "loaded_equals_committed": shadow_load_object_schedule == commit_object_schedule,
                "loaded_equals_cold_stored": shadow_load_object_schedule == cold_store_object_schedule,
                "committed_equals_cold_stored": commit_object_schedule == cold_store_object_schedule,
                "boundary_cold_object_schedules_complete": kernel_witness.map(|kernel_witness| {
                    pre_committed_cold_object_schedule.as_ref()
                        == kernel_witness.emitted_public_object_schedule()
                        && post_committed_cold_object_schedule.as_ref()
                            == kernel_witness.emitted_public_object_schedule()
                }),
                "refines_shell_contract": refines_shell_contract,
            })
        }
        None => json!({
            "present": false,
        }),
    }
}

fn runtime_shell_contract_summary(shell_contract: &RuntimeShellContract) -> JsonValue {
    json!({
        "public_object_count": shell_contract.public_object_universe().len(),
        "public_object_universe": shell_contract.public_object_universe(),
        "canonical_loaded_object_count": shell_contract.canonical_loaded_object_schedule().len(),
        "canonical_loaded_object_schedule": shell_contract.canonical_loaded_object_schedule(),
        "kernel_step_count": shell_contract.kernel_schedule().steps().len(),
        "kernel_opcode_count": shell_contract.kernel_schedule().opcodes().len(),
        "kernel_step_public_object_schedule": shell_contract.kernel_schedule().public_object_schedule(),
    })
}

fn runtime_shell_trace_summary(
    shell_trace: &RuntimeShellTrace,
    shell_contract: Option<&RuntimeShellContract>,
) -> JsonValue {
    let projected_from_events = shell_trace.projected_kernel_schedule_from_events();
    json!({
        "event_count": shell_trace.event_count(),
        "projected_kernel_step_count": shell_trace.projected_kernel_schedule().steps().len(),
        "projected_kernel_opcode_count": shell_trace.projected_kernel_schedule().opcodes().len(),
        "projected_kernel_step_public_object_schedule":
            shell_trace.projected_kernel_schedule().public_object_schedule(),
        "projected_kernel_step_count_from_events": projected_from_events.steps().len(),
        "projected_kernel_step_public_object_schedule_from_events":
            projected_from_events.public_object_schedule(),
        "pre_committed_cold_object_schedule": shell_trace.pre_committed_cold_object_schedule(),
        "shadow_load_object_schedule": shell_trace.shadow_load_object_schedule(),
        "commit_object_schedule": shell_trace.commit_object_schedule(),
        "cold_store_object_schedule": shell_trace.cold_store_object_schedule(),
        "post_committed_cold_object_schedule": shell_trace.post_committed_cold_object_schedule(),
        "summaries_match_events": shell_trace.summaries_match_events(),
        "loaded_equals_committed":
            shell_trace.shadow_load_object_schedule() == shell_trace.commit_object_schedule(),
        "loaded_equals_cold_stored":
            shell_trace.shadow_load_object_schedule() == shell_trace.cold_store_object_schedule(),
        "committed_equals_cold_stored":
            shell_trace.commit_object_schedule() == shell_trace.cold_store_object_schedule(),
        "replays_shell_contract":
            shell_contract.map(|shell_contract| shell_trace.replays_contract(shell_contract)),
        "refines_shell_contract":
            shell_contract.map(|shell_contract| shell_trace.refines_contract(shell_contract)),
    })
}

fn run_target_call_with_seed(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &str,
    args: Vec<Value>,
    deploy_seed: u64,
) -> Result<uo_core::ExecutionTrace> {
    let mut instance = prepare_instance_with_seed(artifact, setup, deploy_seed)?;
    Ok(instance.call(entrypoint, args)?.trace)
}

fn prepare_instance_with_seed(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    deploy_seed: u64,
) -> Result<ContractInstance> {
    let mut instance = ContractInstance::deploy_with_seed(artifact.clone(), deploy_seed)?;
    for call in setup {
        instance.call(call.entrypoint, call.args.clone())?;
    }
    Ok(instance)
}

fn collect_seeded_pathoram_family(
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    entrypoint: &str,
    args: Vec<Value>,
    seed_count: usize,
) -> Result<CollectedSeededFamily> {
    let mut access_counters_before: Option<BTreeMap<u32, u64>> = None;
    let mut witnesses = Vec::with_capacity(seed_count);
    for seed in 0..seed_count {
        let trace =
            run_target_call_with_seed(artifact, setup, entrypoint, args.clone(), seed as u64)?;
        let observed_access_counters = trace.runtime_public_oram_access_counters_before();
        if let Some(expected) = &access_counters_before {
            if expected != &observed_access_counters {
                return Err(anyhow!(
                    "seeded path-ORAM family for {} does not keep pre-call access counters public and stable across seeds",
                    entrypoint
                ));
            }
        } else {
            access_counters_before = Some(observed_access_counters);
        }
        witnesses.push(trace.runtime_refinement_witness()?);
    }
    Ok(CollectedSeededFamily {
        family: SeededRuntimePathOramWitnessFamily::new(witnesses)?,
        access_counters_before: access_counters_before.unwrap_or_default(),
    })
}

fn imported_oram_config(
    artifact: &CompiledArtifact,
    entrypoint: &str,
    witness: &RuntimeRefinementWitness,
    access_counters_before: &BTreeMap<u32, u64>,
) -> Result<ImportedOramConfig> {
    let manifest_entry = artifact
        .contract
        .manifest
        .entrypoints
        .get(entrypoint)
        .ok_or_else(|| anyhow!("manifest entry missing for {}", entrypoint))?;
    Ok(ImportedOramConfig {
        pub_data: ImportedOramPublicData {
            witness: ImportedOramEntrypointWitness {
                manifest: ImportedManifestWitness {
                    public_gas_budget: manifest_entry.public_gas_budget,
                    secret_args: manifest_entry.secret_args.clone(),
                    oram_accesses: manifest_entry
                        .oram_accesses
                        .iter()
                        .map(|(object_id, count)| (*object_id, *count))
                        .collect(),
                },
                entrypoint_id: witness.public_outcome().entrypoint_id.clone(),
                oram_objects: witness.oram_objects().to_vec(),
            },
            public_args: witness.public_outcome().public_args.clone(),
            access_counters: access_counters_before.clone().into_iter().collect(),
        },
        secret_state: Vec::new(),
        secret_args: Vec::new(),
    })
}

fn normalize_path_oram_logical_event(event: &LogicalEvent) -> LogicalEvent {
    let detail = match event.kind.as_str() {
        "uooram_counter" => "counter".to_string(),
        "uooram_metadata_load" => "page:*".to_string(),
        "uooram_path_read" => "bucket:*".to_string(),
        _ => event.detail.clone(),
    };
    LogicalEvent {
        kind: event.kind.clone(),
        object: event.object.clone(),
        detail,
    }
}

fn imported_oram_public_view(witness: &RuntimeRefinementWitness) -> ImportedOramViewPublicPart {
    ImportedOramViewPublicPart {
        opcode_trace: witness.trace().opcode_trace.clone(),
        logical_accesses: witness
            .trace()
            .logical_accesses
            .events()
            .map(|event| normalize_path_oram_logical_event(&event))
            .collect(),
        logical_writes: witness.trace().logical_writes.clone(),
        gas_used: witness.trace().gas_used,
    }
}

fn imported_path_oram_public_location(
    witness: &RuntimeRefinementWitness,
) -> ImportedPathOramStorageLocationTrace {
    ImportedPathOramStorageLocationTrace {
        read_labels: witness
            .trace()
            .physical_reads
            .events()
            .map(|event| ImportedPathOramPhysicalEventLabel {
                object: event.object.clone(),
                location: normalize_path_oram_location(&event.object, &event.location),
            })
            .collect(),
        write_labels: witness
            .trace()
            .physical_writes
            .events()
            .map(|event| ImportedPathOramPhysicalEventLabel {
                object: event.object.clone(),
                location: normalize_path_oram_location(&event.object, &event.location),
            })
            .collect(),
    }
}

fn normalize_path_oram_location(object: &str, location: &str) -> String {
    if location.starts_with(&format!("{object}@bucket")) {
        format!("{object}@bucket*")
    } else {
        location.to_string()
    }
}

fn imported_path_oram_storage_shape(
    witness: &RuntimeRefinementWitness,
) -> ImportedPathOramStorageShape {
    ImportedPathOramStorageShape {
        read_lengths: witness
            .trace()
            .physical_reads
            .events()
            .map(|event| event.len)
            .collect(),
        write_classes: witness
            .trace()
            .physical_writes
            .events()
            .map(|event| event.write_class.clone())
            .collect(),
        write_lengths: witness
            .trace()
            .physical_writes
            .events()
            .map(|event| event.len)
            .collect(),
    }
}

fn hashes_equal<F>(
    class0: &[uo_core::TraceHashBundle],
    class1: &[uo_core::TraceHashBundle],
    project: F,
) -> bool
where
    F: Fn(&uo_core::TraceHashBundle) -> &String,
{
    class0
        .iter()
        .all(|lhs| class1.iter().all(|rhs| project(lhs) == project(rhs)))
}

fn trace_summary(benchmark: &str, mode: &str, outcome: &ExperimentOutcome) -> JsonValue {
    // Exact backends (uo) owe exact physical-trace equality; the ORAM route is
    // related only computationally, so a physical-trace inequality there is an
    // expected computational difference, not a failed obligation.
    let computational = mode.starts_with("oram");
    let mut summary = json!({
        "benchmark": benchmark,
        "mode": mode,
        "comparison_class": if computational { "computational_oram" } else { "exact_backend" },
        "equality_is_obligation": !computational,
        "opcode_equal": outcome.opcode_equal,
        "logical_access_equal": outcome.logical_equal,
        "logical_write_equal": outcome.logical_write_equal,
        "physical_read_equal": outcome.physical_read_equal,
        "physical_trace_equal": outcome.physical_equal,
        "exact_encoding_matches": outcome.exact_encoding_matches,
        "outcome_model_matches": outcome.outcome_model_matches,
        "final_public_state_model_matches": outcome.final_public_state_model_matches,
    });
    // An experiment on an `encrypted_to_client` entrypoint also reports what
    // its runs show of the return channel.
    if let (Some(checks), Some(fields)) = (&outcome.encrypted_return, summary.as_object_mut()) {
        fields.insert("encrypted_return_checks_hold".into(), json!(checks.hold()));
        fields.insert("encrypted_return".into(), json!(checks));
    }
    summary
}

fn extract_metrics(result: &DiagnosticCallResult) -> BTreeMap<String, f64> {
    let trace = &result.call.trace;
    let mut metrics = BTreeMap::new();
    metrics.insert(
        "bytes_read".into(),
        trace
            .physical_reads
            .events()
            .map(|event| event.len)
            .sum::<usize>() as f64,
    );
    metrics.insert(
        "backend_reads".into(),
        trace.physical_reads.event_count() as f64,
    );
    metrics.insert(
        "bytes_written".into(),
        trace
            .physical_writes
            .events()
            .map(|event| event.len)
            .sum::<usize>() as f64,
    );
    metrics.insert(
        "backend_writes".into(),
        trace.physical_writes.event_count() as f64,
    );
    metrics.insert("zero_writes".into(), result.telemetry.zero_writes as f64);
    metrics.insert(
        "update_only_fraction".into(),
        if trace.physical_writes.has_no_event() {
            1.0
        } else {
            trace
                .physical_writes
                .events()
                .filter(|event| event.class == WriteClass::Update)
                .count() as f64
                / trace.physical_writes.event_count() as f64
        },
    );
    metrics.insert(
        "boundary_events".into(),
        trace.theorem_trace.boundary_schedule.len() as f64,
    );
    if let Some(shape) = &trace.theorem_trace.controller_shape {
        metrics.insert(
            "controller_phase_count".into(),
            shape.controller_phase_order.len() as f64,
        );
        metrics.insert(
            "normalized_page_events".into(),
            shape
                .page_trace_regions
                .iter()
                .map(|region| region.event_budget)
                .sum::<usize>() as f64,
        );
    }
    metrics.insert(
        "same_writes".into(),
        trace
            .physical_writes
            .events()
            .filter(|event| event.class == WriteClass::Same)
            .count() as f64,
    );
    metrics.insert(
        "set_writes".into(),
        trace
            .physical_writes
            .events()
            .filter(|event| event.class == WriteClass::Set)
            .count() as f64,
    );
    metrics.insert(
        "clear_writes".into(),
        trace
            .physical_writes
            .events()
            .filter(|event| event.class == WriteClass::Clear)
            .count() as f64,
    );
    metrics.insert(
        "update_writes".into(),
        trace
            .physical_writes
            .events()
            .filter(|event| event.class == WriteClass::Update)
            .count() as f64,
    );
    metrics.insert("gas_used".into(), trace.gas_used as f64);
    metrics
}

fn auc_report(class0: &[BTreeMap<String, f64>], class1: &[BTreeMap<String, f64>]) -> JsonValue {
    let metric_names = metric_names(class0, class1);
    let mut report = serde_json::Map::new();
    for metric in metric_names {
        let negatives = class0
            .iter()
            .map(|metrics| *metrics.get(&metric).unwrap_or(&0.0))
            .collect::<Vec<_>>();
        let positives = class1
            .iter()
            .map(|metrics| *metrics.get(&metric).unwrap_or(&0.0))
            .collect::<Vec<_>>();
        report.insert(metric, json!(auc(&negatives, &positives)));
    }
    JsonValue::Object(report)
}

fn mi_report(class0: &[BTreeMap<String, f64>], class1: &[BTreeMap<String, f64>]) -> JsonValue {
    let metric_names = metric_names(class0, class1);
    let mut report = serde_json::Map::new();
    for metric in metric_names {
        let negatives = class0
            .iter()
            .map(|metrics| *metrics.get(&metric).unwrap_or(&0.0))
            .collect::<Vec<_>>();
        let positives = class1
            .iter()
            .map(|metrics| *metrics.get(&metric).unwrap_or(&0.0))
            .collect::<Vec<_>>();
        report.insert(
            metric,
            json!(mutual_information_bits(&negatives, &positives)),
        );
    }
    JsonValue::Object(report)
}

fn metric_names(
    class0: &[BTreeMap<String, f64>],
    class1: &[BTreeMap<String, f64>],
) -> BTreeSet<String> {
    class0
        .iter()
        .chain(class1.iter())
        .flat_map(|metrics| metrics.keys().cloned())
        .collect()
}

fn auc(negatives: &[f64], positives: &[f64]) -> f64 {
    if negatives.is_empty() || positives.is_empty() {
        return 0.5;
    }
    let mut wins = 0.0;
    for negative in negatives {
        for positive in positives {
            if positive > negative {
                wins += 1.0;
            } else if (*positive - *negative).abs() < f64::EPSILON {
                wins += 0.5;
            }
        }
    }
    wins / ((negatives.len() * positives.len()) as f64)
}

fn mutual_information_bits(negatives: &[f64], positives: &[f64]) -> f64 {
    let total = negatives.len() + positives.len();
    if total == 0 {
        return 0.0;
    }
    let mut counts: BTreeMap<(String, usize), usize> = BTreeMap::new();
    let mut value_counts: BTreeMap<String, usize> = BTreeMap::new();
    for value in negatives {
        let key = format!("{value:.6}");
        *counts.entry((key.clone(), 0)).or_insert(0) += 1;
        *value_counts.entry(key).or_insert(0) += 1;
    }
    for value in positives {
        let key = format!("{value:.6}");
        *counts.entry((key.clone(), 1)).or_insert(0) += 1;
        *value_counts.entry(key).or_insert(0) += 1;
    }
    let label_counts = [negatives.len(), positives.len()];
    let mut mi = 0.0;
    for ((value, label), joint_count) in counts {
        let p_xy = joint_count as f64 / total as f64;
        let p_x = *value_counts.get(&value).unwrap() as f64 / total as f64;
        let p_y = label_counts[label] as f64 / total as f64;
        mi += p_xy * (p_xy / (p_x * p_y)).log2();
    }
    mi
}

fn scenario_summary(result: &ScenarioResult) -> JsonValue {
    json!({
        "executable": true,
        "rejected": false,
        "aborted": result.target.aborted,
        "return": format_value(result.target.return_value.as_ref()),
        "getters": result.getters.iter().map(|value| format_value(value.as_ref())).collect::<Vec<_>>(),
        "gas_used": result.target.trace.gas_used,
        "physical_writes": result.target.trace.physical_writes.event_count(),
    })
}

fn optional_scenario_summary(result: &OptionalScenarioResult) -> JsonValue {
    match result {
        OptionalScenarioResult::Executed(result) => scenario_summary(result),
        OptionalScenarioResult::Rejected { error } => json!({
            "executable": false,
            "rejected": true,
            "error": error,
        }),
    }
}

fn scenario_overhead(result: &ScenarioResult) -> JsonValue {
    json!({
        "executable": true,
        "rejected": false,
        "gas_used": result.target.trace.gas_used,
        "physical_reads": result.target.trace.physical_reads.event_count(),
        "physical_writes": result.target.trace.physical_writes.event_count(),
        "bytes_read": result.target.trace.physical_reads.events().map(|event| event.len).sum::<usize>() as f64,
        "bytes_written": result.target.trace.physical_writes.events().map(|event| event.len).sum::<usize>() as f64,
        "trace_json_bytes": serde_json::to_vec(&result.target.trace)
            .map(|bytes| bytes.len())
            .unwrap_or_default(),
    })
}

fn optional_scenario_overhead(result: &OptionalScenarioResult) -> JsonValue {
    match result {
        OptionalScenarioResult::Executed(result) => scenario_overhead(result),
        OptionalScenarioResult::Rejected { error } => json!({
            "executable": false,
            "rejected": true,
            "error": error,
        }),
    }
}

/// Versioned identifier for the modeled resource-cost accounting reported as
/// `gas_used`. This is a MODELED resource cost, not stock EVM gas: there is no
/// EVM gas schedule or bytecode backend in this toolchain.
const RESOURCE_COST_MODEL: &str = "uo-modeled-resource-cost-v2";

/// Self-describing cost-model record embedded in `overheads.json` so the report
/// is not ambiguous about its `gas_used` wording. The two documented formulas
/// mirror `gas_used_of` in `runtime/uo-evm/src/controller.rs`.
fn cost_model_descriptor() -> JsonValue {
    json!({
        "id": RESOURCE_COST_MODEL,
        "kind": "modeled-resource-units",
        "excludes_stock_evm_gas": true,
        "excludes_evm_gas_schedule": true,
        "excludes_evm_bytecode_backend": true,
        "confidential_formula": "modeled_public_gas = 2000 + statements*11 + expressions*7 + load_ops*29 + commit_ops*29",
        "public_runtime_formula": "logical_reads*3 + logical_writes*5 + physical_writes*17",
    })
}

/// Formula-exactness record for one benchmark backend. A confidential entrypoint
/// (`cost_formula: modeled_static_budget`) must report the compiler's modeled
/// static budget as its runtime cost: the probe independently reads the compiler
/// `public_gas_budget` and the runtime `gas_used` and requires agreement. A
/// public entrypoint (`cost_formula: dynamic_execution_metric`) uses the dynamic
/// execution-metric model documented in `cost_model`. The `confidential` /
/// `public` distinction is carried by `cost_formula` rather than a boolean leaf,
/// so the acceptance gate does not see a spurious `confidential: false` path.
fn scenario_cost_formula(
    result: &ScenarioResult,
    artifact: &CompiledArtifact,
    entrypoint: &str,
    backend: &str,
) -> JsonValue {
    let gas_used = result.target.trace.gas_used;
    let manifest_entry = artifact.contract.manifest.entrypoints.get(entrypoint);
    let manifest_public_gas_budget = manifest_entry.map(|entry| entry.public_gas_budget);
    let confidential = manifest_entry
        .map(|entry| !entry.secret_args.is_empty())
        .unwrap_or(false);
    let (cost_formula, formula_exact) = if confidential {
        (
            "modeled_static_budget",
            manifest_public_gas_budget == Some(gas_used),
        )
    } else {
        ("dynamic_execution_metric", true)
    };
    json!({
        "backend": backend,
        "entrypoint": entrypoint,
        "cost_model": RESOURCE_COST_MODEL,
        "cost_formula": cost_formula,
        "gas_used": gas_used,
        "manifest_public_gas_budget": manifest_public_gas_budget,
        "formula_exact": formula_exact,
    })
}

fn evidence_kind_label(kind: RuntimeBoundaryEvidenceKind) -> &'static str {
    match kind {
        RuntimeBoundaryEvidenceKind::RustVisibility => "rust_visibility",
        RuntimeBoundaryEvidenceKind::GeneratedSchema => "generated_schema",
        RuntimeBoundaryEvidenceKind::LeanTheorem => "lean_theorem",
        RuntimeBoundaryEvidenceKind::ExecutableSemanticRefinement => {
            "executable_semantic_refinement"
        }
        RuntimeBoundaryEvidenceKind::SourceRegression => "source_regression",
    }
}

/// Separation of the runtime-to-Lean boundary obligations into proof-critical
/// and regression-only groups (Issue 14). A proof-critical obligation carries a
/// Lean theorem, generated-schema, executable-refinement, or Rust-visibility
/// (TCB-listed source-frozen) evidence kind; a regression-only obligation is a
/// source-drift regression that backs no proof-critical claim.
/// `validate_runtime_boundary_schema` rejects any proof-critical obligation
/// backed only by source regression, so no proof-critical claim rests solely on
/// a Rust source substring outside the source-frozen TCB surface.
fn runtime_boundary_obligation_classification_json() -> JsonValue {
    let describe = |obligation: &uo_core::RuntimeBoundaryObligation| {
        json!({
            "id": obligation.id,
            "surface": obligation.surface,
            "evidence_kind": evidence_kind_label(obligation.evidence_kind),
            "rust_anchor": obligation.rust_anchor,
            "lean_anchor": obligation.lean_anchor,
            "executable_check": obligation.executable_check,
        })
    };
    let proof_critical = RUNTIME_BOUNDARY_OBLIGATIONS
        .iter()
        .filter(|obligation| obligation.proof_critical)
        .map(describe)
        .collect::<Vec<_>>();
    let regression_only = RUNTIME_BOUNDARY_OBLIGATIONS
        .iter()
        .filter(|obligation| !obligation.proof_critical)
        .map(describe)
        .collect::<Vec<_>>();
    json!({
        "proof_critical_count": proof_critical.len(),
        "regression_only_count": regression_only.len(),
        "proof_critical": proof_critical,
        "regression_only": regression_only,
    })
}

fn overhead_matrix_row(
    benchmark: &str,
    backend_label: &str,
    artifact: &CompiledArtifact,
    entrypoint: &str,
    result: &ScenarioResult,
) -> Result<JsonValue> {
    let mut row = scenario_overhead(result);
    append_artifact_overhead_metadata(&mut row, benchmark, backend_label, artifact, entrypoint)?;
    append_call_start_decode(&mut row, artifact, entrypoint, result)?;
    Ok(row)
}

fn optional_overhead_matrix_row(
    benchmark: &str,
    backend_label: &str,
    artifact: &CompiledArtifact,
    entrypoint: &str,
    result: &OptionalScenarioResult,
) -> Result<JsonValue> {
    let mut row = optional_scenario_overhead(result);
    append_artifact_overhead_metadata(&mut row, benchmark, backend_label, artifact, entrypoint)?;
    Ok(row)
}

fn append_artifact_overhead_metadata(
    row: &mut JsonValue,
    benchmark: &str,
    backend_label: &str,
    artifact: &CompiledArtifact,
    entrypoint: &str,
) -> Result<()> {
    let object = row
        .as_object_mut()
        .ok_or_else(|| anyhow!("overhead row for {} is not a JSON object", benchmark))?;
    object.insert("benchmark".into(), json!(benchmark));
    object.insert("entrypoint".into(), json!(entrypoint));
    object.insert("backend".into(), json!(backend_label));
    object.insert("capacity".into(), json!(artifact_capacity_label(artifact)));
    object.insert(
        "artifact_json_bytes".into(),
        json!(serde_json::to_vec(artifact)?.len()),
    );
    object.insert(
        "state_objects".into(),
        json!(artifact
            .contract
            .state
            .iter()
            .map(|state| json!({
                "name": &state.name,
                "kind": format!("{:?}", state.kind),
                "backend": backend_kind_label(&state.backend),
                "capacity": state.capacity,
                "confidential": state.confidential,
            }))
            .collect::<Vec<_>>()),
    );
    object.insert(
        "entrypoint_resource_bounds".into(),
        match artifact
            .contract
            .manifest
            .entrypoint_resource_bounds(entrypoint)
        {
            Ok(bounds) => json!(bounds),
            Err(err) => json!({ "error": err.to_string() }),
        },
    );
    Ok(())
}

fn artifact_backend_label(artifact: &CompiledArtifact) -> String {
    let mut backends = artifact
        .contract
        .state
        .iter()
        .filter(|object| object.confidential)
        .map(|object| backend_kind_label(&object.backend).to_string())
        .collect::<BTreeSet<_>>();
    if backends.is_empty() {
        backends = artifact
            .contract
            .state
            .iter()
            .map(|object| backend_kind_label(&object.backend).to_string())
            .collect::<BTreeSet<_>>();
    }
    backends.into_iter().collect::<Vec<_>>().join("+")
}

fn backend_kind_label(backend: &BackendKind) -> &'static str {
    match backend {
        BackendKind::Raw => "raw",
        BackendKind::FullScan => "full_scan",
        BackendKind::Oram => "oram",
    }
}

fn artifact_capacity_label(artifact: &CompiledArtifact) -> Option<String> {
    let capacities = artifact
        .contract
        .state
        .iter()
        .filter_map(|object| object.capacity)
        .collect::<BTreeSet<_>>();
    if capacities.is_empty() {
        None
    } else {
        Some(
            capacities
                .into_iter()
                .map(|capacity| capacity.to_string())
                .collect::<Vec<_>>()
                .join("+"),
        )
    }
}

/// What a call reads at its start, outside the trace: for each Path ORAM map
/// the entrypoint touches, the runtime opens the counter and every metadata
/// page, the units the map's first traced access reads, to rebuild each
/// slot's leaf and key (the directory) and the stash in the enclave
/// (`refresh_path_state_from_storage`). It reads no bucket: an access reads
/// its path, and takes the key's value from the key's block. The pattern is
/// fixed by the public parameters, so it reveals nothing. Lengths are the
/// stored ciphertext lengths the trace records for the same units.
fn call_start_decode(
    artifact: &CompiledArtifact,
    entrypoint: &str,
    physical_reads: &uo_core::PhysicalReads,
) -> Result<(usize, usize)> {
    let manifest = &artifact.contract.manifest;
    let entry = manifest
        .entrypoints
        .get(entrypoint)
        .ok_or_else(|| anyhow!("manifest entry missing for {entrypoint}"))?;
    let mut reads = 0usize;
    let mut bytes = 0usize;
    for object_id in entry.oram_accesses.keys() {
        let object = manifest
            .objects
            .iter()
            .find(|object| object.id == *object_id)
            .ok_or_else(|| anyhow!("manifest object {object_id} missing for {entrypoint}"))?;
        let Some(oram) = object.oram.as_ref() else {
            continue;
        };
        if !uo_core::manifest::is_path_oram_scheme(&oram.scheme) {
            continue;
        }
        let traced_len = |unit: &str| -> Result<usize> {
            let prefix = format!("{}@{unit}", object.name);
            physical_reads
                .events()
                .find(|event| event.object == object.name && event.location.starts_with(&prefix))
                .map(|event| event.len)
                .ok_or_else(|| anyhow!("no traced {unit} read for {}", object.name))
        };
        let counter = traced_len("counter")?;
        let page = traced_len("meta")?;
        reads += 1 + oram.metadata_pages;
        bytes += counter + oram.metadata_pages * page;
    }
    Ok((reads, bytes))
}

/// Adds the call-start reads to an overhead row of an entrypoint that touches
/// a Path ORAM map, next to the traced counts.
fn append_call_start_decode(
    row: &mut JsonValue,
    artifact: &CompiledArtifact,
    entrypoint: &str,
    result: &ScenarioResult,
) -> Result<()> {
    let (reads, bytes) =
        call_start_decode(artifact, entrypoint, &result.target.trace.physical_reads)?;
    if reads == 0 {
        return Ok(());
    }
    let traced_reads = result.target.trace.physical_reads.event_count();
    let traced_bytes = result
        .target
        .trace
        .physical_reads
        .events()
        .map(|event| event.len)
        .sum::<usize>();
    let object = row
        .as_object_mut()
        .ok_or_else(|| anyhow!("overhead row for {entrypoint} is not a JSON object"))?;
    object.insert("call_start_reads".into(), json!(reads));
    object.insert("call_start_bytes".into(), json!(bytes as f64));
    object.insert(
        "physical_reads_with_call_start".into(),
        json!(traced_reads + reads),
    );
    object.insert(
        "bytes_read_with_call_start".into(),
        json!((traced_bytes + bytes) as f64),
    );
    Ok(())
}

fn format_value(value: Option<&Value>) -> JsonValue {
    match value {
        Some(Value::Bool(v)) => json!(v),
        Some(Value::Uint(v)) => json!(v),
        Some(Value::Bytes32(bytes)) => json!(format!("0x{}", hex::encode(bytes))),
        Some(Value::Address(bytes)) => json!(format!("0x{}", hex::encode(bytes))),
        Some(other) => json!(other.to_string()),
        None => JsonValue::Null,
    }
}

fn b32(byte: u8) -> Value {
    Value::Bytes32([byte; 32])
}

fn addr(byte: u8) -> Value {
    Value::Address([byte; 20])
}

